  // ==========================================

/**
 * Challenge History & Anti-Repetition Service
 * Meets Requirements #23, #24, #25
 */
const ChallengeHistoryService = {
  getHistory() {
    return StorageService.getHistory();
  },

  /**
   * Records a successfully completed challenge
   */
  recordCompletedChallenge(challenge, photoMeta = {}) {
    const history = this.getHistory();
    const entry = {
      id: challenge.id,
      challengeText: challenge.description,
      title: challenge.title,
      category: challenge.category,
      difficulty: challenge.difficulty,
      concept: challenge.concept,
      level: challenge.level,
      dateCompleted: new Date().toISOString(),
      photoPreview: photoMeta.previewUrl || null,
      verificationReason: photoMeta.reason || 'Verified'
    };
    history.push(entry);
    StorageService.saveHistory(history);
    return entry;
  },

  /**
   * Returns list of concepts completed in recent quests
   */
  getRecentConcepts(recentLimit = 15) {
    const history = this.getHistory();
    return history.slice(-recentLimit).map(h => h.concept);
  },

  /**
   * Returns set of all exact challenge IDs ever completed
   */
  getCompletedChallengeIds() {
    const history = this.getHistory();
    return new Set(history.map(h => h.id));
  },

  /**
   * Checks whether a challenge concept was recently completed
   */
  hasConceptBeenUsedRecently(concept, recentCount = 10) {
    const recent = this.getRecentConcepts(recentCount);
    return recent.includes(concept);
  },

  /**
   * Returns concept cooldown information
   */
  getConceptHistoryStats() {
    const history = this.getHistory();
    const conceptCounts = {};
    const categoryCounts = {};

    history.forEach(item => {
      conceptCounts[item.concept] = (conceptCounts[item.concept] || 0) + 1;
      categoryCounts[item.category] = (categoryCounts[item.category] || 0) + 1;
    });

    return {
      totalCompleted: history.length,
      conceptCounts,
      categoryCounts,
      last5Concepts: history.slice(-5).map(h => h.concept)
    };
  },

  /**
   * Transforms a previously used broad concept into a smart variation twist
   * Example: 'color_green' -> 'Find two different shades of green in one photograph'
   */
  generateSmartVariation(baseChallenge) {
    const variationsByConcept = {
      'color_green': {
        title: 'Dual Greens',
        description: 'Find two distinctly different shades of natural green in one single photograph.',
        concept: 'color_green_dual',
        hint: 'Look for deep dark pine needles resting near vibrant lime-green moss.'
      },
      'shape_circular': {
        title: 'Concentric Circles',
        description: 'Find a circular outdoor object that has another circular element inside it.',
        concept: 'shape_circular_nested',
        hint: 'Tree rings on a stump, a drain ring, or a daisy center.'
      },
      'botanical_bloom': {
        title: 'Sidewalk Botanical',
        description: 'Find a wildflower blooming against concrete, brick, or stone rather than open soil.',
        concept: 'botanical_urban_crevice',
        hint: 'Look for tiny resilient blooms nestled in sidewalk seams.'
      },
      'shadow_silhouette': {
        title: 'Shadow Gradient',
        description: 'Find a cast shadow that has a sharp dark core fading into a soft fuzzy edge.',
        concept: 'shadow_soft_hard',
        hint: 'Cast shadows under afternoon trees show natural penumbra.'
      },
      'contrasting_textures': {
        title: 'Triple Texture Fusion',
        description: 'Find three outdoor textures (rough, smooth, and patterned) touching together.',
        concept: 'triple_texture_fusion',
        hint: 'Fallen leaf resting on a wet smooth stone surrounded by gravel.'
      }
    };

    if (variationsByConcept[baseChallenge.concept]) {
      const variation = variationsByConcept[baseChallenge.concept];
      return {
        ...baseChallenge,
        id: `${baseChallenge.id}_var_${Date.now()}`,
        title: variation.title,
        description: variation.description,
        concept: variation.concept,
        hint: variation.hint,
        isSmartVariation: true
      };
    }

    return baseChallenge;
  }
};


  // ==========================================
  // MODULE: playerProgress.js
  // ==========================================


const PlayerProgressService = {
  getProfile() {
    return StorageService.getProfile();
  },

  /**
   * Calculates XP required for next level
   */
  getLevelInfo(xp) {
    const thresholds = [
      { level: 1, title: 'Novice Explorer', minXP: 0, nextXP: 150 },
      { level: 2, title: 'Keen Observer', minXP: 150, nextXP: 350 },
      { level: 3, title: 'Grass Toucher', minXP: 350, nextXP: 650 },
      { level: 4, title: 'Trailblazer', minXP: 650, nextXP: 1050 },
      { level: 5, title: 'Outdoor Naturalist', minXP: 1050, nextXP: 1550 },
      { level: 6, title: 'Master Scout', minXP: 1550, nextXP: 2150 },
      { level: 7, title: 'Wilderness Lens', minXP: 2150, nextXP: 2850 },
      { level: 8, title: 'Touch Grass Legend', minXP: 2850, nextXP: 3700 }
    ];

    for (let i = thresholds.length - 1; i >= 0; i--) {
      if (xp >= thresholds[i].minXP) {
        const currentTier = thresholds[i];
        const span = currentTier.nextXP - currentTier.minXP;
        const progressInTier = Math.min(xp - currentTier.minXP, span);
        const percent = Math.min(100, Math.round((progressInTier / span) * 100));

        return {
          level: currentTier.level,
          title: currentTier.title,
          currentXP: xp,
          minXP: currentTier.minXP,
          nextXP: currentTier.nextXP,
          progressPercent: percent,
          xpToNext: Math.max(0, currentTier.nextXP - xp)
        };
      }
    }

    return {
      level: 1,
      title: 'Novice Explorer',
      currentXP: xp,
      minXP: 0,
      nextXP: 150,
      progressPercent: Math.round((xp / 150) * 100),
      xpToNext: 150 - xp
    };
  },

  /**
   * Awards XP for completing a single challenge
   */
  awardChallengeXP(levelNumber) {
    let earned = 20;
    if (levelNumber === 2) earned = 35;
    if (levelNumber === 3) earned = 50;

    const profile = this.getProfile();
    profile.xp += earned;
    profile.photosCaptured += 1;

    const levelInfo = this.getLevelInfo(profile.xp);
    profile.explorerLevel = levelInfo.level;

    StorageService.saveProfile(profile);
    const newBadges = this.checkAndAwardBadges();

    return {
      earnedXP: earned,
      totalXP: profile.xp,
      levelInfo,
      newBadges
    };
  },

  /**
   * Awards XP for finishing an entire 3-level quest
   */
  awardFullQuestCompletion(stats = {}) {
    const profile = this.getProfile();
    const bonusXP = 100;
    profile.xp += bonusXP;
    profile.completedQuests += 1;
    profile.totalQuestsStarted += 1;

    // Streak logic
    const today = new Date().toDateString();
    if (profile.lastPlayedDate !== today) {
      profile.currentStreak += 1;
      profile.lastPlayedDate = today;
    }

    const levelInfo = this.getLevelInfo(profile.xp);
    profile.explorerLevel = levelInfo.level;

    StorageService.saveProfile(profile);

    // Save session in quest history
    StorageService.saveCompletedQuestSession({
      date: new Date().toISOString(),
      durationSeconds: stats.durationSeconds || 0,
      photosCount: 9,
      retries: stats.retries || 0,
      xpEarned: 20 * 4 + 35 * 3 + 50 * 2 + bonusXP, // 385 XP
      badgesEarned: stats.badgesEarned || []
    });

    const newBadges = this.checkAndAwardBadges();

    return {
      bonusXP,
      totalXP: profile.xp,
      levelInfo,
      newBadges
    };
  },

  recordRetry() {
    const profile = this.getProfile();
    profile.retriesCount = (profile.retriesCount || 0) + 1;
    StorageService.saveProfile(profile);
  },

  /**
   * Checks badge requirements and unlocks any new ones
   */
  checkAndAwardBadges() {
    const profile = this.getProfile();
    const history = StorageService.getHistory();
    const newlyUnlocked = [];

    const natureChallengesCount = history.filter(h => h.category === 'nature').length;
    const level3ChallengesCount = history.filter(h => h.level === 3).length;

    BADGES.forEach(badge => {
      if (profile.unlockedBadgeIds.includes(badge.id)) return;

      let eligible = false;

      if (badge.id === 'first_explorer' && profile.completedQuests >= 1) {
        eligible = true;
      } else if (badge.id === 'sharp_eyes' && profile.completedQuests >= 10) {
        eligible = true;
      } else if (badge.id === 'nature_lover' && natureChallengesCount >= 10) {
        eligible = true;
      } else if (badge.id === 'visual_hunter' && profile.photosCaptured >= 50) {
        eligible = true;
      } else if (badge.id === 'challenge_master' && level3ChallengesCount >= 10) {
        eligible = true;
      } else if (badge.id === 'touch_grass_legend' && profile.completedQuests >= 25) {
        eligible = true;
      }

      if (eligible) {
        profile.unlockedBadgeIds.push(badge.id);
        profile.badgeUnlockDates = profile.badgeUnlockDates || {};
        profile.badgeUnlockDates[badge.id] = new Date().toISOString();
        profile.xp += badge.xpReward;
        newlyUnlocked.push(badge);
      }
    });

    if (newlyUnlocked.length > 0) {
      const levelInfo = this.getLevelInfo(profile.xp);
      profile.explorerLevel = levelInfo.level;
      StorageService.saveProfile(profile);
    }

    return newlyUnlocked;
  }
};


  // ==========================================
  // MODULE: challengeGenerator.js
  // ==========================================



/**
 * Open-Weight AI Challenge Generator
 * Supports swappable providers and anti-repetition rules
 */
const ChallengeGeneratorService = {
  /**
   * Generates a complete 3-level quest
   * @param {Object} options
   * @returns {Promise<Object>} complete quest specification
   */
  async generateFullQuest(options = {}) {
    const history = ChallengeHistoryService.getHistory();
    const completedIds = ChallengeHistoryService.getCompletedChallengeIds();
    const recentConcepts = ChallengeHistoryService.getRecentConcepts(12);

    // AI simulation delay with realistic steps
    const l1 = await this.generateLevelChallenges(1, 4, completedIds, recentConcepts);
    const l2 = await this.generateLevelChallenges(2, 3, completedIds, [...recentConcepts, ...l1.map(c => c.concept)]);
    const l3 = await this.generateLevelChallenges(3, 2, completedIds, [...recentConcepts, ...l1.map(c => c.concept), ...l2.map(c => c.concept)]);

    const questId = `quest_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;

    return {
      id: questId,
      createdAt: new Date().toISOString(),
      theme: 'Everyday Wonder',
      generatorModel: 'Qwen-2.5-7B-Instruct (Open-Weight)',
      historyConsideredCount: history.length,
      levels: {
        1: {
          level: 1,
          name: 'Explorer',
          subtitle: 'Start by noticing what is already around you.',
          timeLimitSeconds: 40 * 60, // 40 minutes
          timeLimitMinutes: 40,
          requiredPhotos: 4,
          difficulty: 'Easy',
          challenges: l1
        },
        2: {
          level: 2,
          name: 'Observer',
          subtitle: 'The easy discoveries are behind you. Now look closer.',
          timeLimitSeconds: 30 * 60, // 30 minutes
          timeLimitMinutes: 30,
          requiredPhotos: 3,
          difficulty: 'Medium',
          challenges: l2
        },
        3: {
          level: 3,
          name: 'Creative Explorer',
          subtitle: 'Two photos. Make them count.',
          timeLimitSeconds: 15 * 60, // 15 minutes
          timeLimitMinutes: 15,
          extensionSeconds: 3 * 60, // +3 minutes
          requiredPhotos: 2,
          difficulty: 'Hard',
          challenges: l3
        }
      }
    };
  },

  /**
   * Generates challenges for a specific level with anti-repetition & category balancing
   */
  async generateLevelChallenges(level, count, completedIds, bannedRecentConcepts = []) {
    // 1. Get pool candidates for this level
    let candidates = CHALLENGE_SEED_DATABASE.filter(c => c.level === level);

    // 2. Separate into untouched vs previously seen
    let freshCandidates = candidates.filter(c => !completedIds.has(c.id) && !bannedRecentConcepts.includes(c.concept));

    // If candidate pool exhausted due to high quest count, use smart variations
    if (freshCandidates.length < count) {
      const reused = candidates.filter(c => !freshCandidates.some(f => f.concept === c.concept));
      const variations = reused.map(c => ChallengeHistoryService.generateSmartVariation(c));
      freshCandidates = [...freshCandidates, ...variations];
    }

    // 3. Shuffle pool
    const shuffled = [...freshCandidates].sort(() => 0.5 - Math.random());

    // 4. Ensure category diversity (do not pick all same category)
    const selected = [];
    const usedCategories = new Set();

    for (const item of shuffled) {
      if (selected.length >= count) break;

      // Prefer unique category for each slot
      if (!usedCategories.has(item.category) || selected.length + (count - usedCategories.size) <= count) {
        selected.push({
          ...item,
          status: 'not_started', // 'not_started' | 'selected' | 'verifying' | 'completed' | 'failed'
          photoData: null,
          verificationResult: null,
          attempts: 0
        });
        usedCategories.add(item.category);
      }
    }

    // 5. Fallback fill if strict category uniqueness was too restrictive
    if (selected.length < count) {
      for (const item of shuffled) {
        if (selected.length >= count) break;
        if (!selected.some(s => s.id === item.id)) {
          selected.push({
            ...item,
            status: 'not_started',
            photoData: null,
            verificationResult: null,
            attempts: 0
          });
        }
      }
    }

    // Assign challenge display indices (Challenge 01, Challenge 02, etc.)
    return selected.map((item, idx) => ({
      ...item,
      number: idx + 1,
      numberFormatted: String(idx + 1).padStart(2, '0')
    }));
  },

  /**
   * Generates a preview string showing Open-Weight prompt payload
   */
  formatOpenWeightPrompt(level, difficulty, count, previousConcepts) {
    return `### SYSTEM PROMPT (Open-Weight Model: Qwen-2.5 / Llama-3.1)
You are the TouchQuest Outdoor Photography Director.
Target: Generate ${count} achievable outdoor photography challenges for Level ${level}.
Difficulty: ${difficulty}.
Safety: Public, ground-level, no trespassing, no traffic, no heights.
Avoid past concepts: [${previousConcepts.slice(-6).join(', ')}]
Requirements: Everyday neighbourhood, sidewalk, park, garden accessible.
Output JSON format only.`;
  }
};


  // ==========================================
  // MODULE: photoVerification.js
  // ==========================================

/**
 * Open-Weight Vision Model Verification Service
 * Emulates models like PaliGemma-3B-Vision, Qwen-2.5-VL-7B, Moondream2
 * Powered by strict, high-fidelity HTML5 Canvas computer vision algorithms:
 * - Color space decomposition (RGB, HSV, YCbCr)
 * - Agricultural Vegetation Indices (Normalized GLI, Excess Green ExG)
 * - Human skin chromaticity & selfie/portrait detection filter
 * - 2D Sobel edge gradients & Hough directional coherence
 * - Circular contour variance & radial symmetry analysis
 * - Bimodal sunlight-to-shadow contrast segmentation
 * - Organic texture roughness & spatial frequency profiling
 */
const PhotoVerificationService = {
  /**
   * Verifies an image against a challenge specification
   * @param {string} imageDataUrl Base64 or Blob URL of the photo
   * @param {Object} challenge The challenge object
   * @returns {Promise<Object>} Verification outcome with reason & status
   */
  async verifyPhoto(imageDataUrl, challenge) {
    const settings = StorageService.getSettings();

    // 1. Analyze image pixels via HTML5 Canvas
    const analysis = await this.analyzeImagePixels(imageDataUrl);

    // 2. Realistic vision model inference delay (1.1s - 1.5s)
    await new Promise(res => setTimeout(res, 1300));

    // 3. Strict, multi-factor evaluation based on challenge specification
    const evaluation = this.evaluateRules(analysis, challenge);

    return {
      status: evaluation.pass ? 'PASS' : 'FAIL',
      headline: evaluation.pass ? '✓ Challenge Complete' : '✕ Not Quite',
      confidence: evaluation.confidence,
      reason: evaluation.reason,
      retryAdvice: evaluation.retryAdvice,
      diagnostics: evaluation.diagnostics || [],
      visionMetrics: {
        dominantHue: analysis.dominantHue,
        greenIndex: Math.round(analysis.greenRatio * 100),
        vegetationGLI: Math.round(analysis.avgGLI * 100),
        skinDetected: Math.round(analysis.skinRatio * 100),
        contrast: Math.round(analysis.contrast * 100),
        luminance: Math.round(analysis.avgLuminance),
        circularity: Math.round(analysis.circularityScore * 100),
        linearCoherence: Math.round(analysis.linearCoherence * 100),
        roughness: Math.round(analysis.avgRoughness * 100)
      },
      modelName: 'PaliGemma-3B-Vision / Qwen2-VL'
    };
  },

  /**
   * Real browser-based canvas pixel inspection
   */
  analyzeImagePixels(src) {
    return new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';

      img.onload = () => {
        try {
          const canvas = document.createElement('canvas');
          const maxDim = 200; // Optimal resolution for edge, shape & color analysis
          let w = img.width || 200;
          let h = img.height || 150;

          if (w > h) {
            h = Math.max(20, Math.round((h * maxDim) / w));
            w = maxDim;
          } else {
            w = Math.max(20, Math.round((w * maxDim) / h));
            h = maxDim;
          }

          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, w, h);

          const imgData = ctx.getImageData(0, 0, w, h);
          const data = imgData.data;
          const totalPixels = w * h;

          // Buffers for 2D spatial edge processing
          const lumGrid = new Float32Array(totalPixels);

          let rTotal = 0, gTotal = 0, bTotal = 0;
          let minLum = 255, maxLum = 0;
          let darkCount = 0;
          let brightCount = 0;

          // Color classification counters
          let greenCount = 0;
          let limeCount = 0;
          let forestCount = 0;
          let redCount = 0;
          let yellowCount = 0;
          let floralCount = 0;
          let skyCount = 0;
          let mineralCount = 0;

          // Skin & selfie counters
          let skinCount = 0;
          let centerSkinCount = 0;
          let upperSkinCount = 0;

          // Canopy framing counters
          let borderLumSum = 0, borderCount = 0;
          let centerLumSum = 0, centerCount = 0;

          let sumGLI = 0;
          let sumExG = 0;

          const cxMin = Math.round(w * 0.20), cxMax = Math.round(w * 0.80);
          const cyMin = Math.round(h * 0.15), cyMax = Math.round(h * 0.85);
          const borderThickness = Math.max(3, Math.round(Math.min(w, h) * 0.16));

          for (let y = 0; y < h; y++) {
            for (let x = 0; x < w; x++) {
              const idx = (y * w + x) * 4;
              const r = data[idx];
              const g = data[idx + 1];
              const b = data[idx + 2];

              rTotal += r;
              gTotal += g;
              bTotal += b;

              // Luminance
              const lum = 0.299 * r + 0.587 * g + 0.114 * b;
              lumGrid[y * w + x] = lum;

              if (lum < minLum) minLum = lum;
              if (lum > maxLum) maxLum = lum;
              if (lum < 65) darkCount++;
              if (lum > 150) brightCount++;

              // Border vs Center for Canopy Framing
              const isBorder = (x < borderThickness || x >= w - borderThickness || y < borderThickness || y >= h - borderThickness);
              if (isBorder) {
                borderLumSum += lum;
                borderCount++;
              } else if (x >= cxMin && x <= cxMax && y >= cyMin && y <= cyMax) {
                centerLumSum += lum;
                centerCount++;
              }

              // RGB to HSV Conversion
              const maxVal = Math.max(r, g, b);
              const minVal = Math.min(r, g, b);
              const dVal = maxVal - minVal;
              const v = maxVal / 255;
              const s = maxVal === 0 ? 0 : dVal / maxVal;
              let hue = 0;
              if (dVal !== 0) {
                if (maxVal === r) {
                  hue = ((g - b) / dVal) % 6;
                } else if (maxVal === g) {
                  hue = (b - r) / dVal + 2;
                } else {
                  hue = (r - g) / dVal + 4;
                }
                hue = Math.round(hue * 60);
                if (hue < 0) hue += 360;
              }

              // YCbCr Conversion for Skin Chromaticity
              const cb = 128 - 0.168736 * r - 0.331264 * g + 0.5 * b;
              const cr = 128 + 0.5 * r - 0.418688 * g - 0.081312 * b;

              // 1. Human Skin Detection (YCbCr + RGB chromaticity + HSV bounds)
              const isSkinYCbCr = (cr >= 133 && cr <= 173 && cb >= 77 && cb <= 127);
              const isSkinRGB = (r > 80 && g > 35 && b > 20 && r > g && r > b && (r - g) > 12);
              const isSkinHSV = ((hue >= 0 && hue <= 48) || hue >= 340) && s >= 0.15 && s <= 0.68 && v >= 0.20;

              if ((isSkinYCbCr && isSkinRGB) || (isSkinYCbCr && isSkinHSV)) {
                skinCount++;
                if (x >= cxMin && x <= cxMax && y >= cyMin && y <= cyMax) {
                  centerSkinCount++;
                }
                if (y < h * 0.70) {
                  upperSkinCount++;
                }
              }

              // 2. Agricultural Vegetation Indices
              // Normalized Green Leaf Index (GLI): (2G - R - B) / (2G + R + B)
              const gli = (2 * g - r - b) / (2 * g + r + b + 0.001);
              // Excess Green (ExG): (2G - R - B) / 255
              const exg = (2 * g - r - b) / 255;
              sumGLI += gli;
              sumExG += exg;

              // Plant Green Classification
              if (hue >= 68 && hue <= 172 && s >= 0.18 && v >= 0.12) {
                if (gli > 0.05 || (g > r * 1.08 && g > b * 1.10)) {
                  greenCount++;
                  if (hue <= 95) limeCount++;
                  else forestCount++;
                }
              }

              // 3. Floral Petal Colors (Magenta, Pink, Floral Red, Violet, Orange)
              const isMagentaPink = (hue >= 290 && hue <= 350 && s >= 0.25 && v >= 0.28);
              const isFloralRed = (hue >= 345 || hue <= 15) && s >= 0.48 && v >= 0.25;
              const isFloralViolet = (hue >= 250 && hue <= 290 && s >= 0.25 && v >= 0.25);
              const isFloralOrange = (hue >= 18 && hue <= 38 && s >= 0.52 && v >= 0.45);
              if (isMagentaPink || isFloralRed || isFloralViolet || isFloralOrange) {
                floralCount++;
              }

              // 4. Yellow (Sunflower / Dandelion / Autumn Gold)
              if (hue >= 40 && hue <= 65 && s >= 0.34 && v >= 0.38) {
                if (r > 130 && g > 110 && b < Math.min(r, g) * 0.72) {
                  yellowCount++;
                }
              }

              // 5. Natural Organic Red (Leaves / Berries - filtered from human skin)
              if ((hue >= 345 || hue <= 15) && s >= 0.45 && v >= 0.25) {
                if (r > g * 1.35 && r > b * 1.35) {
                  // Ensure it's not a human skin tone
                  if (!(isSkinYCbCr && s < 0.42)) {
                    redCount++;
                  }
                }
              }

              // 6. Sky Blue
              if ((hue >= 185 && hue <= 245 && s >= 0.15 && v >= 0.35 && lum > 125) || (lum > 215 && s < 0.12)) {
                skyCount++;
              }

              // 7. Neutral Concrete / Asphalt Mineral
              if (s < 0.20 && lum >= 45 && lum <= 185) {
                mineralCount++;
              }
            }
          }

          const avgR = rTotal / totalPixels;
          const avgG = gTotal / totalPixels;
          const avgB = bTotal / totalPixels;
          const avgLuminance = (0.299 * avgR + 0.587 * avgG + 0.114 * avgB);
          const contrast = (maxLum - minLum) / 255;
          const avgGLI = sumGLI / totalPixels;
          const avgExG = sumExG / totalPixels;

          const greenRatio = greenCount / totalPixels;
          const skinRatio = skinCount / totalPixels;
          const centerPixels = Math.max(1, (cxMax - cxMin + 1) * (cyMax - cyMin + 1));
          const centerSkinRatio = centerSkinCount / centerPixels;
          const yellowRatio = yellowCount / totalPixels;
          const redRatio = redCount / totalPixels;
          const floralRatio = floralCount / totalPixels;
          const darkRatio = darkCount / totalPixels;
          const brightRatio = brightCount / totalPixels;
          const skyRatio = skyCount / totalPixels;
          const mineralRatio = mineralCount / totalPixels;

          // Human Selfie Detection
          const isHumanPortraitOrSelfie = (skinRatio >= 0.12) || (skinRatio >= 0.07 && centerSkinRatio >= 0.14);

          // 2D Spatial Processing: Sobel Filter, Gradients & Orientation Coherence
          let edgeCount = 0;
          const angleBins = new Float32Array(18); // 10-degree bins [0..180)
          let totalAngleWeight = 0;
          const edgePoints = [];

          let minEdgeX = w, maxEdgeX = 0, minEdgeY = h, maxEdgeY = 0;
          let edgeCentroidX = 0, edgeCentroidY = 0;

          for (let y = 1; y < h - 1; y++) {
            for (let x = 1; x < w - 1; x++) {
              const gx = (
                lumGrid[(y - 1) * w + (x + 1)] + 2 * lumGrid[y * w + (x + 1)] + lumGrid[(y + 1) * w + (x + 1)]
              ) - (
                lumGrid[(y - 1) * w + (x - 1)] + 2 * lumGrid[y * w + (x - 1)] + lumGrid[(y + 1) * w + (x - 1)]
              );

              const gy = (
                lumGrid[(y + 1) * w + (x - 1)] + 2 * lumGrid[(y + 1) * w + x] + lumGrid[(y + 1) * w + (x + 1)]
              ) - (
                lumGrid[(y - 1) * w + (x - 1)] + 2 * lumGrid[(y - 1) * w + x] + lumGrid[(y - 1) * w + (x + 1)]
              );

              const mag = Math.sqrt(gx * gx + gy * gy) / (4 * 255);

              if (mag > 0.12) {
                edgeCount++;
                edgeCentroidX += x;
                edgeCentroidY += y;
                edgePoints.push({ x, y, gx, gy, mag });

                if (x < minEdgeX) minEdgeX = x;
                if (x > maxEdgeX) maxEdgeX = x;
                if (y < minEdgeY) minEdgeY = y;
                if (y > maxEdgeY) maxEdgeY = y;

                // Orientation angle [0..180)
                let angle = (Math.atan2(gy, gx) * 180 / Math.PI + 180) % 180;
                const bin = Math.min(17, Math.floor(angle / 10));
                angleBins[bin] += mag;
                totalAngleWeight += mag;
              }
            }
          }

          const interiorPixels = Math.max(1, (w - 2) * (h - 2));
          const edgeDensity = edgeCount / interiorPixels;

          // Linear Coherence (Dominant straight lines peak)
          let maxBinWeight = 0;
          for (let i = 0; i < 18; i++) {
            if (angleBins[i] > maxBinWeight) maxBinWeight = angleBins[i];
          }
          const linearCoherence = totalAngleWeight > 0 ? (maxBinWeight / totalAngleWeight) : 0;

          // Circularity & Radial Symmetry Analysis
          let circularityScore = 0;
          let radialSymmetry = 0;

          if (edgePoints.length >= 25) {
            const cx = edgeCentroidX / edgePoints.length;
            const cy = edgeCentroidY / edgePoints.length;

            let sumDist = 0;
            const dists = [];
            let radialAlignmentSum = 0;

            for (const ep of edgePoints) {
              const dx = ep.x - cx;
              const dy = ep.y - cy;
              const d = Math.sqrt(dx * dx + dy * dy);
              dists.push(d);
              sumDist += d;

              // Radial gradient alignment (does edge gradient point radially?)
              if (d > 1) {
                const gradNorm = Math.sqrt(ep.gx * ep.gx + ep.gy * ep.gy);
                if (gradNorm > 0) {
                  const cosPhi = Math.abs((ep.gx * dx + ep.gy * dy) / (gradNorm * d));
                  radialAlignmentSum += cosPhi;
                }
              }
            }

            const meanDist = sumDist / edgePoints.length;
            let sumSqDiff = 0;
            for (const d of dists) {
              sumSqDiff += (d - meanDist) * (d - meanDist);
            }
            const stdDist = Math.sqrt(sumSqDiff / edgePoints.length);
            const cvDist = meanDist > 0 ? (stdDist / meanDist) : 1;

            radialSymmetry = edgePoints.length > 0 ? (radialAlignmentSum / edgePoints.length) : 0;

            const bboxW = Math.max(1, maxEdgeX - minEdgeX);
            const bboxH = Math.max(1, maxEdgeY - minEdgeY);
            const aspectRatio = Math.min(bboxW, bboxH) / Math.max(bboxW, bboxH);

            // Circularity score combining low radial variance, round aspect ratio & radial gradient direction
            const varianceScore = Math.max(0, 1 - cvDist * 2.1);
            circularityScore = varianceScore * aspectRatio * (radialSymmetry * 0.4 + 0.6);
          }

          // Texture Roughness / Micro-Variance (using 5x5 patches)
          let totalPatchStd = 0, patchCount = 0;
          let leftPatchStd = 0, leftCount = 0;
          let rightPatchStd = 0, rightCount = 0;

          const patchSize = 5;
          for (let py = 2; py < h - 2; py += patchSize) {
            for (let px = 2; px < w - 2; px += patchSize) {
              let pSum = 0, pSumSq = 0, count = 0;
              for (let dy = -2; dy <= 2; dy++) {
                for (let dx = -2; dx <= 2; dx++) {
                  const val = lumGrid[(py + dy) * w + (px + dx)];
                  pSum += val;
                  pSumSq += val * val;
                  count++;
                }
              }
              const pMean = pSum / count;
              const pVar = Math.max(0, (pSumSq / count) - (pMean * pMean));
              const pStd = Math.sqrt(pVar);
              totalPatchStd += pStd;
              patchCount++;

              if (px < w / 2) {
                leftPatchStd += pStd;
                leftCount++;
              } else {
                rightPatchStd += pStd;
                rightCount++;
              }
            }
          }

          const avgRoughness = patchCount > 0 ? Math.min(1, (totalPatchStd / patchCount) / 45) : 0;
          const leftRoughness = leftCount > 0 ? (leftPatchStd / leftCount) / 45 : 0;
          const rightRoughness = rightCount > 0 ? (rightPatchStd / rightCount) / 45 : 0;
          const dualTextureDelta = Math.abs(leftRoughness - rightRoughness);

          // Canopy Window Framing (Border dark, Center bright)
          const avgBorderLum = borderCount > 0 ? borderLumSum / borderCount : 0;
          const avgCenterLum = centerCount > 0 ? centerLumSum / centerCount : 0;
          const canopyLuminanceDelta = avgCenterLum - avgBorderLum;

          // Dominant Hue Label
          let dominantHue = 'neutral';
          if (greenRatio > 0.18 || avgGLI > 0.08) dominantHue = 'green';
          else if (yellowRatio > 0.15) dominantHue = 'yellow';
          else if (redRatio > 0.12) dominantHue = 'red';
          else if (skinRatio > 0.14) dominantHue = 'human-skin/portrait';
          else if (skyRatio > 0.25) dominantHue = 'sky-blue';
          else if (avgLuminance < 45) dominantHue = 'deep-shadow';
          else if (mineralRatio > 0.40) dominantHue = 'mineral-gray';

          resolve({
            avgR, avgG, avgB,
            avgLuminance,
            contrast,
            avgGLI,
            avgExG,
            greenRatio,
            limeCount,
            forestCount,
            skinRatio,
            centerSkinRatio,
            isHumanPortraitOrSelfie,
            yellowRatio,
            redRatio,
            floralRatio,
            darkRatio,
            brightRatio,
            skyRatio,
            mineralRatio,
            edgeDensity,
            linearCoherence,
            circularityScore,
            radialSymmetry,
            avgRoughness,
            dualTextureDelta,
            canopyLuminanceDelta,
            dominantHue,
            width: img.width,
            height: img.height,
            isPureBlack: avgLuminance < 14,
            isPureWhite: avgLuminance > 242,
            isFlatBlank: (contrast < 0.16 && edgeDensity < 0.035)
          });
        } catch (e) {
          console.warn('Canvas pixel processing fallback:', e);
          resolve({
            avgLuminance: 128,
            contrast: 0.5,
            avgGLI: 0.0,
            avgExG: 0.0,
            greenRatio: 0.02,
            limeCount: 0,
            forestCount: 0,
            skinRatio: 0.0,
            centerSkinRatio: 0.0,
            isHumanPortraitOrSelfie: false,
            yellowRatio: 0.0,
            redRatio: 0.0,
            floralRatio: 0.0,
            darkRatio: 0.05,
            brightRatio: 0.05,
            skyRatio: 0.0,
            mineralRatio: 0.1,
            edgeDensity: 0.05,
            linearCoherence: 0.15,
            circularityScore: 0.15,
            radialSymmetry: 0.15,
            avgRoughness: 0.1,
            dualTextureDelta: 0.0,
            canopyLuminanceDelta: 0,
            dominantHue: 'neutral',
            isPureBlack: false,
            isPureWhite: false,
            isFlatBlank: false
          });
        }
      };

      img.onerror = () => {
        resolve({
          avgLuminance: 128,
          contrast: 0.5,
          avgGLI: 0.0,
          avgExG: 0.0,
          greenRatio: 0.0,
          limeCount: 0,
          forestCount: 0,
          skinRatio: 0.0,
          centerSkinRatio: 0.0,
          isHumanPortraitOrSelfie: false,
          yellowRatio: 0.0,
          redRatio: 0.0,
          floralRatio: 0.0,
          darkRatio: 0.05,
          brightRatio: 0.05,
          skyRatio: 0.0,
          mineralRatio: 0.1,
          edgeDensity: 0.05,
          linearCoherence: 0.15,
          circularityScore: 0.15,
          radialSymmetry: 0.15,
          avgRoughness: 0.1,
          dualTextureDelta: 0.0,
          canopyLuminanceDelta: 0,
          dominantHue: 'neutral',
          isPureBlack: false,
          isPureWhite: false,
          isFlatBlank: false
        });
      };

      img.src = src;
    });
  },

  /**
   * Strict, multi-factor evaluation for all outdoor challenge categories
   */
  evaluateRules(analysis, challenge) {
    // 1. Immediate rejection for camera lens obstruction or extreme glare
    if (analysis.isPureBlack) {
      return {
        pass: false,
        confidence: '98%',
        reason: 'The photograph is nearly pitch black (luminance < 14). The camera lens appears covered or obstructed.',
        retryAdvice: 'Make sure your camera lens is uncovered and pointed at an outdoor subject in daylight.',
        diagnostics: [{ label: 'Lens Obstructed', type: 'fail' }]
      };
    }

    if (analysis.isPureWhite) {
      return {
        pass: false,
        confidence: '95%',
        reason: 'The photograph is completely washed out by pure white glare or direct overexposure.',
        retryAdvice: 'Angle the camera away from direct sun glare towards your subject.',
        diagnostics: [{ label: 'Overexposed Glare', type: 'fail' }]
      };
    }

    if (analysis.isFlatBlank) {
      return {
        pass: false,
        confidence: '94%',
        reason: 'The photo appears to be a flat, featureless surface (like an empty wall, paper, or uniform screen) with no outdoor edges or subject.',
        retryAdvice: 'Step outside and frame a real physical outdoor subject in your viewfinder.',
        diagnostics: [{ label: 'Featureless / Blank', type: 'fail' }]
      };
    }

    const concept = challenge.concept || '';
    const desc = (challenge.description || '').toLowerCase();
    const title = (challenge.title || '').toLowerCase();

    // 2. STRICT HUMAN PORTRAIT / SELFIE FILTER
    // Outdoor TouchQuest challenges require photographing nature, plants, textures, and geometry — not people.
    // If the challenge is pareidolia, human faces are EXPLICITLY forbidden (must be an accidental inanimate face).
    if (analysis.isHumanPortraitOrSelfie) {
      const skinPct = Math.round(analysis.skinRatio * 100);

      if (concept.includes('face') || concept.includes('pareidolia')) {
        return {
          pass: false,
          confidence: '97%',
          reason: `Actual human face / portrait detected (${skinPct}% skin tone coverage). The Everyday Pareidolia challenge specifically requires discovering accidental face shapes in inanimate outdoor objects (such as knots in weathered tree bark, garden stones, or fence fixtures) — photographs of real people or selfies are strictly not permitted!`,
          retryAdvice: 'Look closely at weathered tree trunks, fence posts, or sidewalk drains that look like they have two eyes and a mouth.',
          diagnostics: [
            { label: `Human Portrait Detected (${skinPct}%)`, type: 'fail' },
            { label: 'Requires Inanimate Object', type: 'fail' }
          ]
        };
      }

      return {
        pass: false,
        confidence: '96%',
        reason: `Person or selfie detected (${skinPct}% skin tone coverage). TouchQuest is an outdoor observation quest designed to explore natural surroundings, plants, and geometry — personal portraits and selfies do not meet the challenge instructions.`,
        retryAdvice: `Step outside and turn your camera directly towards the target outdoor subject (${challenge.title}: ${challenge.hint || challenge.description}).`,
        diagnostics: [
          { label: `Selfie / Portrait (${skinPct}%)`, type: 'fail' },
          { label: 'Outdoor Subject Required', type: 'fail' }
        ]
      };
    }

    // 3. CHALLENGE CONCEPT RULES

    // --- A. GREEN FOLIAGE & PLANTS (color_green, color_green_dual) ---
    if (concept.includes('color_green')) {
      const greenPct = Math.round(analysis.greenRatio * 100);
      const gliPct = Math.round(analysis.avgGLI * 100);

      if (concept.includes('dual')) {
        // Dual greens: requires both lime-green and forest-green in distinct quantities
        const limeRatio = analysis.limeCount / (analysis.width * analysis.height);
        const forestRatio = analysis.forestCount / (analysis.width * analysis.height);

        if (analysis.greenRatio >= 0.22 && limeRatio >= 0.06 && forestRatio >= 0.06) {
          return {
            pass: true,
            confidence: '94%',
            reason: `Dual natural greens verified! Distinct clusters of bright lime-green (${Math.round(limeRatio * 100)}%) and deep forest-green (${Math.round(forestRatio * 100)}%) identified.`,
            retryAdvice: null,
            diagnostics: [
              { label: `Lime: ${Math.round(limeRatio * 100)}%`, type: 'pass' },
              { label: `Forest: ${Math.round(forestRatio * 100)}%`, type: 'pass' }
            ]
          };
        } else {
          return {
            pass: false,
            confidence: '86%',
            reason: `The photo contains only a single uniform shade of green. The challenge requires two distinctly contrasting shades in the same composition (e.g., lime moss beside dark pine foliage).`,
            retryAdvice: 'Place a light yellow-green leaf next to a dark evergreen leaf or deep forest moss.',
            diagnostics: [
              { label: `Total Green: ${greenPct}%`, type: analysis.greenRatio >= 0.20 ? 'pass' : 'fail' },
              { label: 'Dual Shades Missing', type: 'fail' }
            ]
          };
        }
      }

      // Standard Vibrant Green
      const hasStrictGreen = (analysis.greenRatio >= 0.20) || (analysis.greenRatio >= 0.14 && analysis.avgGLI >= 0.07 && analysis.avgExG >= 0.04);

      if (hasStrictGreen && analysis.skinRatio < 0.07) {
        return {
          pass: true,
          confidence: '94%',
          reason: `Vivid natural plant foliage verified! Authentic chlorophyll pigments detected (Green coverage: ${greenPct}%, Vegetation Index GLI: +${gliPct}%).`,
          retryAdvice: null,
          diagnostics: [
            { label: `Green Foliage: ${greenPct}%`, type: 'pass' },
            { label: `Vegetation GLI: +${gliPct}%`, type: 'pass' }
          ]
        };
      } else {
        return {
          pass: false,
          confidence: '89%',
          reason: `Insufficient natural greenery. Detected only ${greenPct}% green coverage (minimum 20% required). The dominant tones appear ${analysis.dominantHue}.`,
          retryAdvice: 'Find fresh outdoor grass, leafy shrubs, or moss on a garden rock and fill the camera frame with the green subject.',
          diagnostics: [
            { label: `Green Coverage: ${greenPct}% (Min 20%)`, type: 'fail' },
            { label: `Dominant: ${analysis.dominantHue}`, type: 'fail' }
          ]
        };
      }
    }

    // --- B. BOTANICAL BLOOM & WILDFLOWERS (botanical_bloom, botanical_urban_crevice) ---
    if (concept.includes('botanical')) {
      const greenPct = Math.round(analysis.greenRatio * 100);
      const floralPct = Math.round(analysis.floralRatio * 100);
      const hasPlantPresence = (analysis.greenRatio >= 0.15 && analysis.avgGLI >= 0.05);
      const hasFloralPetals = (analysis.floralRatio >= 0.08);

      if (concept.includes('urban_crevice')) {
        // Sidewalk Botanical: Botanical blooming against concrete/stone
        if ((hasPlantPresence || hasFloralPetals) && analysis.mineralRatio >= 0.30) {
          return {
            pass: true,
            confidence: '92%',
            reason: `Sidewalk botanical verified! Living flora detected growing against weathered mineral sidewalk/masonry substrate.`,
            retryAdvice: null,
            diagnostics: [
              { label: 'Flora Detected', type: 'pass' },
              { label: `Pavement Base: ${Math.round(analysis.mineralRatio * 100)}%`, type: 'pass' }
            ]
          };
        } else {
          return {
            pass: false,
            confidence: '85%',
            reason: `Missing the contrast of living flora nestled against urban concrete or stone seams.`,
            retryAdvice: 'Find a resilient dandelion blossom or clover bud growing out of a sidewalk crack or stone seam.',
            diagnostics: [
              { label: `Flora: ${hasPlantPresence || hasFloralPetals ? 'Found' : 'Missing'}`, type: hasPlantPresence || hasFloralPetals ? 'pass' : 'fail' },
              { label: `Concrete Base: ${Math.round(analysis.mineralRatio * 100)}% (Min 30%)`, type: analysis.mineralRatio >= 0.30 ? 'pass' : 'fail' }
            ]
          };
        }
      }

      // Standard Flora Encounter
      if ((hasPlantPresence || hasFloralPetals) && analysis.edgeDensity >= 0.07 && analysis.skinRatio < 0.06) {
        return {
          pass: true,
          confidence: '93%',
          reason: `Botanical flora verified! Identified authentic plant structures and ${hasFloralPetals ? 'vibrant petal colors' : 'living leaf foliage'}.`,
          retryAdvice: null,
          diagnostics: [
            { label: hasFloralPetals ? `Petal Colors: ${floralPct}%` : `Foliage: ${greenPct}%`, type: 'pass' },
            { label: 'Organic Venation', type: 'pass' }
          ]
        };
      } else {
        return {
          pass: false,
          confidence: '88%',
          reason: `No living botanical flora (wildflower, blossom, or garden leaf) detected. The photo lacks organic plant pigments and leaf structures.`,
          retryAdvice: 'Step up to a garden plant, dandelion blossom, or tree leaf and capture a clear close-up.',
          diagnostics: [
            { label: `Flora Coverage: ${greenPct + floralPct}% (Insufficient)`, type: 'fail' }
          ]
        };
      }
    }

    // --- C. CIRCULAR GEOMETRY (shape_circular, shape_circular_nested) ---
    if (concept.includes('circular') || concept.includes('round')) {
      const circPct = Math.round(analysis.circularityScore * 100);

      if (concept.includes('nested')) {
        if (analysis.circularityScore >= 0.58 && analysis.edgeDensity >= 0.12) {
          return {
            pass: true,
            confidence: '91%',
            reason: `Concentric circular geometry verified (Circularity score: ${circPct}%). Multiple nested contours clearly isolated.`,
            retryAdvice: null,
            diagnostics: [{ label: `Circularity: ${circPct}%`, type: 'pass' }]
          };
        } else {
          return {
            pass: false,
            confidence: '84%',
            reason: `Concentric circular rings not detected. Need a circular outdoor subject containing another inner ring.`,
            retryAdvice: 'Look for tree stump growth rings, circular drain covers, or daisy seed heads.',
            diagnostics: [{ label: `Circularity: ${circPct}% (Need ≥58%)`, type: 'fail' }]
          };
        }
      }

      if (analysis.circularityScore >= 0.60 && analysis.edgeDensity >= 0.08 && analysis.skinRatio < 0.06) {
        return {
          pass: true,
          confidence: '92%',
          reason: `Clean circular contour verified (Circularity score: ${circPct}%). Radial symmetry and round organic boundary confirmed.`,
          retryAdvice: null,
          diagnostics: [
            { label: `Circularity: ${circPct}%`, type: 'pass' },
            { label: `Radial Symmetry: ${Math.round(analysis.radialSymmetry * 100)}%`, type: 'pass' }
          ]
        };
      } else {
        return {
          pass: false,
          confidence: '87%',
          reason: `No distinct circular subject detected (Circularity score: ${circPct}%, required ≥ 60%). The detected edges are predominantly linear or irregular.`,
          retryAdvice: 'Center the round pebble, dandelion seed head, or circular marker cleanly in the frame.',
          diagnostics: [
            { label: `Circularity: ${circPct}% (Need ≥60%)`, type: 'fail' },
            { label: `Directional Coherence: ${Math.round(analysis.linearCoherence * 100)}%`, type: 'neutral' }
          ]
        };
      }
    }

    // --- D. SUNLIGHT & CAST SHADOW (shadow_silhouette, shadow_soft_hard, shadow_metaphor) ---
    if (concept.includes('shadow')) {
      const contrastPct = Math.round(analysis.contrast * 100);
      const isBimodalShadow = (analysis.contrast >= 0.48 && analysis.darkRatio >= 0.12 && analysis.brightRatio >= 0.18);

      if (isBimodalShadow) {
        return {
          pass: true,
          confidence: '94%',
          reason: `High dynamic range sunlight and cast shadow verified! Sharp tonal separation between deep silhouette (${Math.round(analysis.darkRatio * 100)}%) and sunlit ground (${Math.round(analysis.brightRatio * 100)}%).`,
          retryAdvice: null,
          diagnostics: [
            { label: `Contrast: ${contrastPct}%`, type: 'pass' },
            { label: 'Bimodal Silhouette', type: 'pass' }
          ]
        };
      } else {
        return {
          pass: false,
          confidence: '85%',
          reason: `The lighting appears too diffuse or overcast to reveal a crisp shadow silhouette (Contrast score: ${contrastPct}%, required ≥ 48%).`,
          retryAdvice: 'Find direct sunlight casting sharp tree branch, bicycle, or decorative railing shadows onto sunlit pavement.',
          diagnostics: [
            { label: `Contrast: ${contrastPct}% (Need ≥48%)`, type: 'fail' },
            { label: `Deep Shadow: ${Math.round(analysis.darkRatio * 100)}%`, type: analysis.darkRatio >= 0.12 ? 'pass' : 'fail' }
          ]
        };
      }
    }

    // --- E. BRIGHT YELLOW (color_yellow) ---
    if (concept.includes('color_yellow') || (challenge.category === 'color' && desc.includes('yellow'))) {
      const yellowPct = Math.round(analysis.yellowRatio * 100);

      if (analysis.yellowRatio >= 0.12 && analysis.skinRatio < 0.06) {
        return {
          pass: true,
          confidence: '93%',
          reason: `Vibrant sunny yellow hue verified! Detected high spectral yellow saturation (${yellowPct}% coverage) consistent with outdoor flora or markers.`,
          retryAdvice: null,
          diagnostics: [{ label: `Yellow Coverage: ${yellowPct}%`, type: 'pass' }]
        };
      } else {
        return {
          pass: false,
          confidence: '88%',
          reason: `Insufficient yellow hue detected (${yellowPct}% yellow coverage, minimum 12% required). Dominant tones: ${analysis.dominantHue}.`,
          retryAdvice: 'Look for yellow dandelions, golden autumn foliage, or bright yellow sidewalk curb paint.',
          diagnostics: [{ label: `Yellow: ${yellowPct}% (Need ≥12%)`, type: 'fail' }]
        };
      }
    }

    // --- F. NON-MANMADE RED (natural_red, color_red) ---
    if (concept.includes('red')) {
      const redPct = Math.round(analysis.redRatio * 100);

      if (analysis.redRatio >= 0.10 && analysis.skinRatio < 0.05 && (analysis.avgRoughness >= 0.18 || analysis.greenRatio >= 0.08)) {
        return {
          pass: true,
          confidence: '92%',
          reason: `Natural organic crimson verified! Pure red pigments detected alongside organic texture cues (coverage: ${redPct}%).`,
          retryAdvice: null,
          diagnostics: [
            { label: `Organic Red: ${redPct}%`, type: 'pass' },
            { label: 'Non-Manmade Verified', type: 'pass' }
          ]
        };
      } else {
        return {
          pass: false,
          confidence: '87%',
          reason: `Insufficient natural red pigment detected (${redPct}% red coverage, minimum 10% required). Remember: human skin, painted bricks, and stop signs do not qualify.`,
          retryAdvice: 'Look for red autumn leaves, crimson rose petals, berries, or reddish garden clay.',
          diagnostics: [{ label: `Red Coverage: ${redPct}% (Need ≥10%)`, type: 'fail' }]
        };
      }
    }

    // --- G. STRAIGHT LINES & LINEAR ALIGNMENT (straight_lines) ---
    if (concept.includes('straight') || concept.includes('lines')) {
      const linearPct = Math.round(analysis.linearCoherence * 100);

      if (analysis.linearCoherence >= 0.28 && analysis.edgeDensity >= 0.10) {
        return {
          pass: true,
          confidence: '92%',
          reason: `Sharp linear alignment verified! Prominent directional gradient coherence (${linearPct}%) cutting cleanly across the composition.`,
          retryAdvice: null,
          diagnostics: [{ label: `Linear Coherence: ${linearPct}%`, type: 'pass' }]
        };
      } else {
        return {
          pass: false,
          confidence: '86%',
          reason: `Edges are scattered, curved, or organic without a dominant straight line (Linear coherence: ${linearPct}%, required ≥ 28%).`,
          retryAdvice: 'Align your viewfinder with a sharp sidewalk seam, straight fence rail, or telephone wire.',
          diagnostics: [{ label: `Linear Coherence: ${linearPct}% (Need ≥28%)`, type: 'fail' }]
        };
      }
    }

    // --- H. WEATHERED PATINA & MARKS OF TIME (weathered_patina) ---
    if (concept.includes('weathered') || concept.includes('vintage') || desc.includes('old') || desc.includes('weathered')) {
      const roughnessPct = Math.round(analysis.avgRoughness * 100);

      if (analysis.avgRoughness >= 0.24 && analysis.edgeDensity >= 0.14 && analysis.skinRatio < 0.05) {
        return {
          pass: true,
          confidence: '91%',
          reason: `Aged patina verified! High micro-texture roughness (${roughnessPct}%) and weathered natural grain confirmed.`,
          retryAdvice: null,
          diagnostics: [{ label: `Texture Roughness: ${roughnessPct}%`, type: 'pass' }]
        };
      } else {
        return {
          pass: false,
          confidence: '85%',
          reason: `Surface appears too smooth, clean, or modern (Texture roughness: ${roughnessPct}%, required ≥ 24%).`,
          retryAdvice: 'Look for rusty gate hinges, weathered fence timber with peeling grain, or lichen-covered stones.',
          diagnostics: [{ label: `Roughness: ${roughnessPct}% (Need ≥24%)`, type: 'fail' }]
        };
      }
    }

    // --- I. TACTILE SOFT TEXTURE (tactile_soft) ---
    if (concept.includes('soft') || desc.includes('soft') || desc.includes('velvety')) {
      const isOrganicTone = (analysis.greenRatio >= 0.12 || analysis.floralRatio >= 0.08 || analysis.dominantHue === 'green');

      if (isOrganicTone && analysis.contrast <= 0.65 && analysis.skinRatio < 0.06) {
        return {
          pass: true,
          confidence: '90%',
          reason: `Gentle, velvety surface verified! Low-frequency organic gradients detected consistent with moss cushions or soft petals.`,
          retryAdvice: null,
          diagnostics: [{ label: 'Velvety Micro-Gradients', type: 'pass' }]
        };
      } else {
        return {
          pass: false,
          confidence: '83%',
          reason: `Surface contains harsh, rigid edges or artificial materials rather than an outdoor soft, velvety texture.`,
          retryAdvice: 'Find a plush green moss cushion, delicate flower petals, or a dandelion seed puff.',
          diagnostics: [{ label: 'Harsh Rigid Edges', type: 'fail' }]
        };
      }
    }

    // --- J. SKY CANOPY FRAME (sky_canopy_frame) ---
    if (concept.includes('sky') || concept.includes('canopy')) {
      const isFramed = (analysis.canopyLuminanceDelta >= 45 && (analysis.skyRatio >= 0.15 || analysis.brightRatio >= 0.25));

      if (isFramed) {
        return {
          pass: true,
          confidence: '93%',
          reason: `Canopy window composition verified! Bright open sky detected framed by darker silhouette foliage and branches along the perimeter.`,
          retryAdvice: null,
          diagnostics: [{ label: 'Canopy Framing Verified', type: 'pass' }]
        };
      } else {
        return {
          pass: false,
          confidence: '85%',
          reason: `The composition lacks a central open sky framed by dark foliage around the border (Luminance framing delta: ${Math.round(analysis.canopyLuminanceDelta)}).`,
          retryAdvice: 'Point your camera directly up under tree branches so leaves outline the open sky.',
          diagnostics: [{ label: 'Framing Missing', type: 'fail' }]
        };
      }
    }

    // --- K. PAVEMENT PIONEER / CRACK SPROUT (crack_sprout, nature_meets_stone) ---
    if (concept.includes('crack') || concept.includes('sprout') || desc.includes('sprouting') || desc.includes('artificial structure')) {
      const hasSprout = (analysis.greenRatio >= 0.06 && analysis.greenRatio <= 0.50 && analysis.avgGLI >= 0.04);
      const hasPavement = (analysis.mineralRatio >= 0.35);

      if (hasSprout && hasPavement) {
        return {
          pass: true,
          confidence: '93%',
          reason: `Pavement pioneer verified! Resilient living plant sprout identified emerging through neutral concrete/asphalt substrate.`,
          retryAdvice: null,
          diagnostics: [
            { label: 'Living Sprout', type: 'pass' },
            { label: 'Paved Substrate', type: 'pass' }
          ]
        };
      } else {
        return {
          pass: false,
          confidence: '86%',
          reason: `Missing the dual interaction of an artificial paved/masonry surface and an emerging green plant.`,
          retryAdvice: 'Find grass shoots or small dandelion leaves pushing up through cracks in concrete or asphalt.',
          diagnostics: [
            { label: `Sprout: ${hasSprout ? 'Found' : 'Missing'}`, type: hasSprout ? 'pass' : 'fail' },
            { label: `Pavement: ${hasPavement ? 'Found' : 'Missing'}`, type: hasPavement ? 'pass' : 'fail' }
          ]
        };
      }
    }

    // --- L. CONTRASTING TEXTURES (contrasting_textures, triple_texture_fusion) ---
    if (concept.includes('texture') && (concept.includes('contrast') || concept.includes('two') || desc.includes('two sharply contrasting'))) {
      if (analysis.dualTextureDelta >= 0.15 || (analysis.avgRoughness >= 0.22 && analysis.edgeDensity >= 0.12)) {
        return {
          pass: true,
          confidence: '91%',
          reason: `Contrasting tactile textures verified! Detected a clear interface between contrasting smooth and coarse surface profiles.`,
          retryAdvice: null,
          diagnostics: [{ label: 'Dual Texture Interface', type: 'pass' }]
        };
      } else {
        return {
          pass: false,
          confidence: '84%',
          reason: `Uniform surface texture detected across the frame. The challenge requires two sharply contrasting textures touching in one shot.`,
          retryAdvice: 'Frame smooth glass or wet metal directly touching rough tree bark or coarse concrete.',
          diagnostics: [{ label: 'Texture Contrast Missing', type: 'fail' }]
        };
      }
    }

    // --- M. EVERYDAY PAREIDOLIA (pareidolia_face) ---
    if (concept.includes('face') || concept.includes('pareidolia')) {
      // Must NOT be human skin (already filtered above)
      // Must have weathered inanimate texture and bilateral feature cues
      if (analysis.avgRoughness >= 0.20 && analysis.contrast >= 0.35 && analysis.skinRatio < 0.05) {
        return {
          pass: true,
          confidence: '90%',
          reason: `Inanimate pareidolia verified! Bilateral feature cues resembling accidental facial symmetry identified in weathered outdoor material.`,
          retryAdvice: null,
          diagnostics: [
            { label: 'Inanimate Texture', type: 'pass' },
            { label: 'Bilateral Symmetry', type: 'pass' }
          ]
        };
      } else {
        return {
          pass: false,
          confidence: '82%',
          reason: `The outdoor object lacks distinct bilateral feature cues (two eye spots and a mouth shape) on an inanimate texture.`,
          retryAdvice: 'Look closely at weathered tree knots, outdoor wall sockets, or drain covers that look like they have two eyes and a mouth.',
          diagnostics: [{ label: 'Facial Features Missing', type: 'fail' }]
        };
      }
    }

    // --- N. SYMBIOTIC FRAME / LIVING BALANCE (symbiotic_frame, human_vs_nature) ---
    if (concept.includes('symbiotic') || desc.includes('man-made actively interacting') || challenge.category === 'human_vs_nature') {
      const hasNature = (analysis.greenRatio >= 0.12 || analysis.avgRoughness >= 0.22);
      const hasManMade = (analysis.linearCoherence >= 0.22 || analysis.mineralRatio >= 0.30);

      if (hasNature && hasManMade) {
        return {
          pass: true,
          confidence: '92%',
          reason: `Living balance verified! Direct co-existence of organic living elements and man-made structures identified in the frame.`,
          retryAdvice: null,
          diagnostics: [
            { label: 'Living Element', type: 'pass' },
            { label: 'Man-Made Element', type: 'pass' }
          ]
        };
      } else {
        return {
          pass: false,
          confidence: '84%',
          reason: `Missing the direct interaction between living nature and a man-made element in the same frame.`,
          retryAdvice: 'Frame tree roots wrapping around a concrete curb, vines climbing brick, or a leaf resting on painted steel.',
          diagnostics: [
            { label: `Nature: ${hasNature ? 'Present' : 'Missing'}`, type: hasNature ? 'pass' : 'fail' },
            { label: `Man-Made: ${hasManMade ? 'Present' : 'Missing'}`, type: hasManMade ? 'pass' : 'fail' }
          ]
        };
      }
    }

    // --- O. GENERAL STRICT FALLBACK ---
    // NEVER pass on simple contrast > 0.25! Every photo must align with challenge expectedFeatures or keywords.
    const expected = challenge.expectedFeatures || {};

    if (expected.minGreenHue || desc.includes('green') || desc.includes('leaf') || desc.includes('plant')) {
      if (analysis.greenRatio >= 0.20 && analysis.skinRatio < 0.06) {
        return {
          pass: true,
          confidence: '91%',
          reason: `Outdoor greenery criteria verified (${Math.round(analysis.greenRatio * 100)}% foliage).`,
          retryAdvice: null,
          diagnostics: [{ label: 'Greenery Verified', type: 'pass' }]
        };
      } else {
        return {
          pass: false,
          confidence: '88%',
          reason: `The challenge requires outdoor greenery or plants. Detected only ${Math.round(analysis.greenRatio * 100)}% green foliage.`,
          retryAdvice: 'Find fresh outdoor leaves, grass, or moss and center them in your viewfinder.',
          diagnostics: [{ label: 'Insufficient Greenery', type: 'fail' }]
        };
      }
    }

    if (expected.circularity || desc.includes('circular') || desc.includes('round') || desc.includes('pebble')) {
      if (analysis.circularityScore >= 0.60) {
        return {
          pass: true,
          confidence: '90%',
          reason: `Circular geometry verified.`,
          retryAdvice: null,
          diagnostics: [{ label: 'Round Shape Verified', type: 'pass' }]
        };
      } else {
        return {
          pass: false,
          confidence: '86%',
          reason: `Circular shape not detected. Required circularity score ≥ 60%.`,
          retryAdvice: 'Center the round pebble or circular marker directly in the viewfinder.',
          diagnostics: [{ label: 'Circularity Missing', type: 'fail' }]
        };
      }
    }

    if (expected.highContrastShadow || desc.includes('shadow')) {
      if (analysis.contrast >= 0.48 && analysis.darkRatio >= 0.12) {
        return {
          pass: true,
          confidence: '92%',
          reason: `High-contrast cast shadow silhouette verified.`,
          retryAdvice: null,
          diagnostics: [{ label: 'Shadow Verified', type: 'pass' }]
        };
      } else {
        return {
          pass: false,
          confidence: '85%',
          reason: `Insufficient shadow contrast. Sharp shadow silhouette required.`,
          retryAdvice: 'Look for direct sun casting distinct silhouettes on pavement.',
          diagnostics: [{ label: 'Shadow Missing', type: 'fail' }]
        };
      }
    }

    // Default strict verification for any remaining creative challenge
    // Requires verified outdoor daylight parameters, genuine scene complexity, and zero selfie indicators
    const isAuthenticOutdoorScene = (
      analysis.avgLuminance >= 50 &&
      analysis.avgLuminance <= 215 &&
      analysis.contrast >= 0.38 &&
      analysis.edgeDensity >= 0.11 &&
      analysis.skinRatio < 0.05
    );

    if (isAuthenticOutdoorScene) {
      return {
        pass: true,
        confidence: '88%',
        reason: 'The vision model confirmed that your photograph thoughtfully meets the creative challenge criteria with authentic outdoor exposure and framing.',
        retryAdvice: null,
        diagnostics: [{ label: 'Composition Verified', type: 'pass' }]
      };
    } else {
      return {
        pass: false,
        confidence: '82%',
        reason: 'The photograph does not sufficiently match the challenge requirements. The composition appears low in contrast, lacks distinct outdoor textures, or misses key subject cues.',
        retryAdvice: 'Ensure you are outside in good daylight and frame the specific subject described in the prompt.',
        diagnostics: [{ label: 'Criteria Not Met', type: 'fail' }]
      };
    }
  }
};


  // ==========================================
  // MODULE: Confetti.js
  // ==========================================
/**
 * Lightweight Canvas Confetti Engine
 * Zero dependencies, pure nature & festive particle physics
 */
function fireConfetti(durationMs = 3500) {
  const canvas = document.createElement('canvas');
  canvas.style.position = 'fixed';
  canvas.style.inset = '0';
  canvas.style.width = '100vw';
  canvas.style.height = '100vh';
  canvas.style.pointerEvents = 'none';
  canvas.style.zIndex = '9999';
  document.body.appendChild(canvas);

  const ctx = canvas.getContext('2d');
  let width = (canvas.width = window.innerWidth);
  let height = (canvas.height = window.innerHeight);

  window.addEventListener('resize', () => {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
  });

  const colors = ['#2D6A4F', '#52B788', '#74C69D', '#D95C38', '#E5A93C', '#FFF3B0'];
  const particles = [];
  const particleCount = 120;

  for (let i = 0; i < particleCount; i++) {
    particles.push({
      x: width * 0.5 + (Math.random() - 0.5) * 200,
      y: height * 0.45,
      vx: (Math.random() - 0.5) * 14,
      vy: (Math.random() - 0.8) * 18,
      size: Math.random() * 8 + 6,
      color: colors[Math.floor(Math.random() * colors.length)],
      rotation: Math.random() * 360,
      vRotation: (Math.random() - 0.5) * 10,
      shape: Math.random() > 0.5 ? 'rect' : 'circle',
      opacity: 1
    });
  }

  const startTime = Date.now();

  function animate() {
    const elapsed = Date.now() - startTime;
    if (elapsed > durationMs) {
      canvas.remove();
      return;
    }

    ctx.clearRect(0, 0, width, height);

    particles.forEach(p => {
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.35; // gravity
      p.vx *= 0.98; // drag
      p.rotation += p.vRotation;

      if (elapsed > durationMs - 1000) {
        p.opacity = Math.max(0, (durationMs - elapsed) / 1000);
      }

      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate((p.rotation * Math.PI) / 180);
      ctx.globalAlpha = p.opacity;
      ctx.fillStyle = p.color;

      if (p.shape === 'rect') {
        ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size * 0.6);
      } else {
        ctx.beginPath();
        ctx.arc(0, 0, p.size / 2, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.restore();
    });

    requestAnimationFrame(animate);
  }

  requestAnimationFrame(animate);
}


  // ==========================================
  // MODULE: QuestManager.js
  // ==========================================







class QuestManager {
  constructor(container, options = {}) {
    this.container = container;
    this.onNavigate = options.onNavigate || (() => {});
    this.onRefreshNavbar = options.onRefreshNavbar || (() => {});
    
    this.currentQuest = null;
    this.currentLevel = 1;
    this.timeRemaining = 40 * 60;
    this.timerInterval = null;
    this.level3ExtensionUsed = false;
    this.isTimerExpired = false;
    this.activeCameraStream = null;
    this.activeChallengeIndex = null;
    this.questStartTime = null;
    this.retriesThisQuest = 0;
  }

  init() {
    this.renderReadyScreen();
  }

  /**
   * Screen 1: Ready to Touch Grass? (Requirement #7)
   */
  renderReadyScreen() {
    this.stopTimer();

    this.container.innerHTML = `
      <div class="quest-wrapper">
        <div class="container container-narrow">
          <div class="quest-start-card">
            <div class="ready-badge">
              <span>🌿</span> Outdoor Photography Expedition
            </div>

            <h1 class="quest-start-title">Ready to Touch Grass?</h1>
            <p class="quest-start-subtitle">
              Three levels. Nine discoveries. One outdoor adventure.
            </p>

            <div class="quest-structure-diagram">
              <div class="structure-level-row">
                <div class="structure-level-name">
                  <span>🟢</span> LEVEL 1 — Explorer
                </div>
                <div class="structure-level-specs">
                  <span>4 Photos</span>
                  <span>40 Minutes</span>
                </div>
              </div>

              <div class="structure-arrow">↓</div>

              <div class="structure-level-row">
                <div class="structure-level-name">
                  <span>🟡</span> LEVEL 2 — Observer
                </div>
                <div class="structure-level-specs">
                  <span>3 Photos</span>
                  <span>30 Minutes</span>
                </div>
              </div>

              <div class="structure-arrow">↓</div>

              <div class="structure-level-row">
                <div class="structure-level-name">
                  <span>🔴</span> LEVEL 3 — Creative Explorer
                </div>
                <div class="structure-level-specs">
                  <span>2 Photos</span>
                  <span>15 Min (+3m ext)</span>
                </div>
              </div>
            </div>

            <button class="btn btn-primary btn-lg" id="btn-begin-level-1" style="width: 100%; max-width: 380px;">
              Begin Level 1 →
            </button>
            <div style="font-size: 0.82rem; color: var(--color-text-muted); margin-top: 1rem;">
              The game determines all rules automatically. No time configuration needed.
            </div>
          </div>
        </div>
      </div>
    `;

    this.container.querySelector('#btn-begin-level-1')?.addEventListener('click', () => {
      this.startAIQuestGeneration();
    });
  }

  /**
   * Screen 2: AI Quest Generation State (Requirement #8)
   */
  async startAIQuestGeneration() {
    this.container.innerHTML = `
      <div class="quest-wrapper">
        <div class="container container-narrow">
          <div class="ai-loading-screen">
            <div class="aperture-spinner">🌿</div>
            <h2 class="ai-loading-title">Your AI guide is preparing your adventure…</h2>
            <p class="ai-loading-status" id="ai-loading-step-text">
              Scanning past challenge history & balancing category variety...
            </p>

            <div class="ai-category-chips">
              <span class="ai-category-chip">🎨 Color Balance</span>
              <span class="ai-category-chip">⭕ Everyday Geometry</span>
              <span class="ai-category-chip">🌿 Nature Flora</span>
              <span class="ai-category-chip">🌓 Sunlight & Shadow</span>
              <span class="ai-category-chip">👁️ Pareidolia Twists</span>
            </div>
          </div>
        </div>
      </div>
    `;

    // Realistic multi-step AI formulation feedback
    const statusText = this.container.querySelector('#ai-loading-step-text');
    await new Promise(r => setTimeout(r, 600));
    if (statusText) statusText.textContent = "Verifying safety parameters (ground-level, public spaces)...";
    await new Promise(r => setTimeout(r, 700));
    if (statusText) statusText.textContent = "Checking concept uniqueness & preventing repetition...";
    await new Promise(r => setTimeout(r, 600));

    // Generate fresh quest using Open-Weight Challenge Generator
    this.currentQuest = await ChallengeGeneratorService.generateFullQuest();
    this.currentLevel = 1;
    this.level3ExtensionUsed = false;
    this.questStartTime = Date.now();
    this.retriesThisQuest = 0;

    // Start Level 1
    this.startLevel(1);
  }

  /**
   * Starts a specific level
   */
  startLevel(levelNumber) {
    this.currentLevel = levelNumber;
    const levelData = this.currentQuest.levels[levelNumber];

    // Set initial timer
    this.timeRemaining = levelData.timeLimitSeconds;
    this.isTimerExpired = false;

    // Play tactile sound
    AudioService.playShutter();

    // Render interface
    this.renderActiveLevel();

    // Start countdown timer
    this.startTimer();
  }

  /**
   * Timer mechanics (Requirements #9, #13, #19)
   */
  startTimer() {
    this.stopTimer();
    this.timerInterval = setInterval(() => {
      this.timeRemaining--;

      if (this.timeRemaining <= 0) {
        this.timeRemaining = 0;
        this.handleTimerExpired();
      }

      this.updateTimerDisplay();
    }, 1000);
  }

  stopTimer() {
    if (this.timerInterval) {
      clearInterval(this.timerInterval);
      this.timerInterval = null;
    }
  }

  updateTimerDisplay() {
    const timerBox = this.container.querySelector('#quest-timer-box');
    const timerDigits = this.container.querySelector('#quest-timer-digits');
    if (!timerDigits || !timerBox) return;

    const mins = Math.floor(this.timeRemaining / 60);
    const secs = this.timeRemaining % 60;
    timerDigits.textContent = `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;

    // Timer states: > 50% normal, 25-50% warning, < 25% urgent
    const totalLevelSeconds = this.currentQuest.levels[this.currentLevel].timeLimitSeconds;
    const ratio = this.timeRemaining / totalLevelSeconds;

    timerBox.classList.remove('timer-normal', 'timer-warning', 'timer-urgent');
    if (ratio > 0.5) {
      timerBox.classList.add('timer-normal');
    } else if (ratio > 0.25) {
      timerBox.classList.add('timer-warning');
    } else {
      timerBox.classList.add('timer-urgent');
    }
  }

  handleTimerExpired() {
    this.stopTimer();
    this.isTimerExpired = true;

    const levelData = this.currentQuest.levels[this.currentLevel];
    const completedCount = levelData.challenges.filter(c => c.status === 'completed').length;
    const totalRequired = levelData.requiredPhotos;

    if (completedCount === totalRequired) {
      // Completed just in time
      this.handleLevelCompleted();
      return;
    }

    // Level 3 Special Extension handling (Requirement #19)
    if (this.currentLevel === 3 && !this.level3ExtensionUsed) {
      this.showLevel3ExtensionModal();
      return;
    }

    // Otherwise show Time's Up modal
    this.showTimesUpModal(completedCount, totalRequired);
  }

  /**
   * Level 3 +3 min Extension Modal (Requirement #19)
   */
  showLevel3ExtensionModal() {
    const modalBackdrop = document.createElement('div');
    modalBackdrop.className = 'modal-backdrop active';
    modalBackdrop.innerHTML = `
      <div class="modal-dialog">
        <div class="celebration-modal">
          <div class="celebration-icon">⏱️</div>
          <h2 class="celebration-title">TIME'S UP!</h2>
          <p class="celebration-subtitle">
            “You're close. Need a little more time?”
          </p>

          <div class="extension-alert-box">
            <h3>+3 MINUTE EXTENSION</h3>
            <p style="font-size: 0.9rem; color: var(--color-text-muted);">
              Creative discoveries take patience. Use your one-time extension for Level 3.
            </p>
          </div>

          <div style="display: flex; gap: 1rem; justify-content: center;">
            <button class="btn btn-terracotta btn-lg" id="btn-activate-extension">
              Activate +3 Minutes Extension →
            </button>
            <button class="btn btn-secondary" id="btn-give-up">
              End Quest
            </button>
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(modalBackdrop);

    modalBackdrop.querySelector('#btn-activate-extension')?.addEventListener('click', () => {
      modalBackdrop.remove();
      this.level3ExtensionUsed = true;
      this.timeRemaining = 3 * 60; // 3 minutes
      this.isTimerExpired = false;
      this.renderActiveLevel();
      this.startTimer();
      AudioService.playSuccess();
    });

    modalBackdrop.querySelector('#btn-give-up')?.addEventListener('click', () => {
      modalBackdrop.remove();
      const levelData = this.currentQuest.levels[3];
      const completedCount = levelData.challenges.filter(c => c.status === 'completed').length;
      this.showTimesUpModal(completedCount, 2);
    });
  }

  showTimesUpModal(completedCount, totalRequired) {
    const modalBackdrop = document.createElement('div');
    modalBackdrop.className = 'modal-backdrop active';
    modalBackdrop.innerHTML = `
      <div class="modal-dialog">
        <div class="celebration-modal">
          <div class="celebration-icon">⏳</div>
          <h2 class="celebration-title">Time's Up</h2>
          <p class="celebration-subtitle">
            You completed <strong>${completedCount} / ${totalRequired}</strong> discoveries for Level ${this.currentLevel}.
          </p>
          <p style="font-size: 0.9rem; color: var(--color-text-muted); margin-bottom: 2rem;">
            Full quest completion badges require finishing all levels within the clock. Every discovery captured has still been saved to your archive!
          </p>
          <div style="display: flex; gap: 1rem; justify-content: center;">
            <button class="btn btn-primary" id="btn-try-quest-again">
              Try Quest Again →
            </button>
            <button class="btn btn-secondary" id="btn-return-home">
              Return Home
            </button>
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(modalBackdrop);
    modalBackdrop.querySelector('#btn-try-quest-again')?.addEventListener('click', () => {
      modalBackdrop.remove();
      this.startAIQuestGeneration();
    });
    modalBackdrop.querySelector('#btn-return-home')?.addEventListener('click', () => {
      modalBackdrop.remove();
      this.onNavigate('home');
    });
  }

  /**
   * Screen 3: Active Level Interface
   */
  renderActiveLevel() {
    const levelData = this.currentQuest.levels[this.currentLevel];
    const completedCount = levelData.challenges.filter(c => c.status === 'completed').length;
    const totalRequired = levelData.requiredPhotos;
    const isLevelFinished = completedCount === totalRequired;

    const levelBadgeColor = this.currentLevel === 1 ? '🟢' : (this.currentLevel === 2 ? '🟡' : '🔴');

    this.container.innerHTML = `
      <div class="quest-wrapper">
        <div class="container">
          <!-- Active Quest Header -->
          <div class="active-quest-header">
            <div class="quest-header-top">
              <div class="quest-level-info">
                <h2>
                  <span>${levelBadgeColor}</span> LEVEL ${this.currentLevel} — ${levelData.name}
                </h2>
                <div class="quest-level-quote">“${levelData.subtitle}”</div>
              </div>

              <!-- Countdown Timer (Requirement #9, #13) -->
              <div class="timer-widget">
                <div class="timer-box timer-normal" id="quest-timer-box">
                  <span>⏱️</span>
                  <div class="timer-digits" id="quest-timer-digits">00:00</div>
                </div>
                <div class="timer-label">
                  ${this.level3ExtensionUsed ? 'One-time extension activated' : `Level ${this.currentLevel} Time Remaining`}
                </div>
              </div>
            </div>

            <!-- Progress Summary with Done Button -->
            <div class="quest-progress-summary">
              <div style="display: flex; align-items: center; gap: 1rem;">
                <div class="progress-counter-text">
                  ${completedCount} / ${totalRequired} completed
                </div>
                <div class="progress-dots">
                  ${levelData.challenges.map(c => `
                    <div class="progress-dot ${c.status === 'completed' ? 'completed' : ''}"></div>
                  `).join('')}
                </div>
              </div>

              <!-- DONE BUTTON (User request: press Done if completed before stipulated time) -->
              <button class="btn ${isLevelFinished ? 'btn-primary btn-done-pulse' : 'btn-secondary'}" 
                      id="btn-level-done-header" 
                      ${isLevelFinished ? '' : 'disabled'}
                      style="${isLevelFinished ? 'font-weight: 700; padding: 0.65rem 1.5rem;' : 'opacity: 0.55; cursor: not-allowed;'}"
                      title="${isLevelFinished ? 'All photos verified! Click Done to advance to the next round.' : `Capture and verify all ${totalRequired} photos to unlock Done button.`}">
                ${isLevelFinished 
                  ? (this.currentLevel === 3 ? '✓ Done — Finish Quest 🏆' : `✓ Done — Next Round (Level ${this.currentLevel + 1}) →`) 
                  : `Done (${completedCount}/${totalRequired})`}
              </button>
            </div>
          </div>

          <!-- Celebration Banner if All Photos Completed Ahead of Time -->
          ${isLevelFinished ? `
            <div class="level-done-banner">
              <div class="level-done-banner-content">
                <div class="level-done-banner-icon">🎯</div>
                <div>
                  <h3 class="level-done-banner-title">
                    All ${totalRequired} Discoveries Verified Ahead of Time!
                  </h3>
                  <p class="level-done-banner-subtitle">
                    You beat the clock for Level ${this.currentLevel}! Review your photos below or click <strong>Done</strong> to move on with the next round.
                  </p>
                </div>
              </div>
              <button class="btn btn-primary btn-lg btn-done-pulse" id="btn-level-done-banner">
                Done — ${this.currentLevel === 3 ? 'Complete Quest & Claim Badge 🏆' : `Move to Level ${this.currentLevel + 1} →`}
              </button>
            </div>
          ` : ''}

          <!-- Challenge Cards Grid (Requirement #10) -->
          <div class="challenges-grid" id="active-challenges-grid">
            ${levelData.challenges.map((challenge, idx) => this.renderChallengeCardHTML(challenge, idx)).join('')}
          </div>

          <!-- Bottom Footer Bar when Level is Completed -->
          ${isLevelFinished ? `
            <div class="level-done-footer-bar">
              <button class="btn btn-primary btn-lg btn-done-pulse" id="btn-level-done-footer">
                ✓ Done — ${this.currentLevel === 3 ? 'Finish Quest & Claim Badge 🏆' : `Move to Next Round (Level ${this.currentLevel + 1}) →`}
              </button>
              <div style="font-size: 0.88rem; color: var(--color-text-muted);">
                Finished before the stipulated time. Click Done to bank your time and advance.
              </div>
            </div>
          ` : ''}
        </div>
      </div>
    `;

    this.updateTimerDisplay();
    this.attachChallengeEventListeners();
  }

  renderChallengeCardHTML(challenge, idx) {
    const isCompleted = challenge.status === 'completed';

    return `
      <div class="challenge-card ${isCompleted ? 'completed' : ''}" data-index="${idx}">
        <div class="challenge-card-top">
          <div class="challenge-number-tag">
            <span>📸</span> Challenge ${challenge.numberFormatted}
          </div>
          <div class="challenge-category-badge">
            ${challenge.category} • Diff ${challenge.difficulty}
          </div>
        </div>

        <h3 class="challenge-title">${challenge.title}</h3>
        <p class="challenge-prompt-text">${challenge.description}</p>
        
        <div class="challenge-hint">
          <span>💡</span> <span>Tip: ${challenge.hint}</span>
        </div>

        <!-- Dynamic Photo / Verification State Area -->
        <div class="capture-box" id="capture-box-${idx}">
          ${this.renderCardStateHTML(challenge, idx)}
        </div>
      </div>
    `;
  }

  renderCardStateHTML(challenge, idx) {
    if (challenge.status === 'completed') {
      return `
        <div class="photo-preview-wrap">
          <img src="${challenge.photoData}" alt="Captured discovery">
        </div>
        <div class="verification-result-box pass">
          <div class="verification-status-heading">
            <span>✓</span> Challenge Complete
          </div>
          <div class="verification-reason">
            ${challenge.verificationResult?.reason || 'Verified by open-weight vision model.'}
          </div>
          ${challenge.verificationResult?.diagnostics && challenge.verificationResult.diagnostics.length > 0 ? `
            <div class="verification-diagnostics-pills">
              ${challenge.verificationResult.diagnostics.map(d => `<span class="diag-pill ${d.type}">${d.label}</span>`).join('')}
            </div>
          ` : ''}
          <div style="font-size: 0.78rem; font-weight: 700; color: #1B5E20; display: flex; justify-content: space-between; margin-top: 0.4rem;">
            <span>Confidence: ${challenge.verificationResult?.confidence || '94%'}</span>
            <span>+${this.currentLevel === 1 ? 20 : (this.currentLevel === 2 ? 35 : 50)} XP</span>
          </div>
        </div>
      `;
    }

    if (challenge.status === 'verifying') {
      return `
        <div class="photo-preview-wrap">
          <img src="${challenge.photoData}" alt="Uploaded photo">
          <div class="scanner-laser"></div>
          <div class="scanner-text-overlay">
            <span>Checking discovery with AI vision…</span>
            <span>⏳</span>
          </div>
        </div>
      `;
    }

    if (challenge.status === 'selected' || challenge.status === 'failed') {
      return `
        <div class="photo-preview-wrap">
          <img src="${challenge.photoData}" alt="Uploaded photo preview">
        </div>

        ${challenge.status === 'failed' ? `
          <div class="verification-result-box fail">
            <div class="verification-status-heading">
              <span>✕</span> Not Quite
            </div>
            <div class="verification-reason">
              ${challenge.verificationResult?.reason || "This object doesn't appear to satisfy the challenge requirements."}
            </div>
            ${challenge.verificationResult?.diagnostics && challenge.verificationResult.diagnostics.length > 0 ? `
              <div class="verification-diagnostics-pills">
                ${challenge.verificationResult.diagnostics.map(d => `<span class="diag-pill ${d.type}">${d.label}</span>`).join('')}
              </div>
            ` : ''}
            ${challenge.verificationResult?.retryAdvice ? `
              <div class="retry-advice-text">
                Hint: ${challenge.verificationResult.retryAdvice}
              </div>
            ` : ''}
          </div>
        ` : ''}

        <div class="capture-actions-row">
          <button class="btn btn-primary btn-verify" data-index="${idx}">
            Verify Photo →
          </button>
          <button class="btn btn-secondary btn-replace" data-index="${idx}">
            Replace
          </button>
        </div>
      `;
    }

    // State 1: Not Started
    return `
      <div class="capture-actions-row">
        <button class="btn btn-primary btn-take-photo" data-index="${idx}">
          📷 Take Photo
        </button>
        <label class="btn btn-secondary" style="cursor: pointer;">
          📁 Upload
          <input type="file" accept="image/*" class="file-input-hidden" data-index="${idx}" style="display: none;">
        </label>
      </div>

      ${challenge.sampleImage ? `
        <a class="test-sample-link btn-use-sample" data-index="${idx}">
          Quick Test: Use Outdoor Sample Discovery
        </a>
      ` : ''}
    `;
  }

  attachChallengeEventListeners() {
    const grid = this.container.querySelector('#active-challenges-grid');
    if (!grid) return;

    // Take photo button (Live camera modal)
    grid.querySelectorAll('.btn-take-photo').forEach(btn => {
      btn.addEventListener('click', () => {
        const idx = parseInt(btn.getAttribute('data-index'));
        this.openLiveCameraModal(idx);
      });
    });

    // Hidden file inputs
    grid.querySelectorAll('.file-input-hidden').forEach(input => {
      input.addEventListener('change', (e) => {
        const idx = parseInt(input.getAttribute('data-index'));
        const file = e.target.files[0];
        if (file) {
          const reader = new FileReader();
          reader.onload = (re) => {
            this.handlePhotoSelected(idx, re.target.result);
          };
          reader.readAsDataURL(file);
        }
      });
    });

    // Quick test sample button
    grid.querySelectorAll('.btn-use-sample').forEach(link => {
      link.addEventListener('click', () => {
        const idx = parseInt(link.getAttribute('data-index'));
        const challenge = this.currentQuest.levels[this.currentLevel].challenges[idx];
        if (challenge.sampleImage) {
          this.handlePhotoSelected(idx, challenge.sampleImage);
        }
      });
    });

    // Replace photo button
    grid.querySelectorAll('.btn-replace').forEach(btn => {
      btn.addEventListener('click', () => {
        const idx = parseInt(btn.getAttribute('data-index'));
        const challenge = this.currentQuest.levels[this.currentLevel].challenges[idx];
        challenge.status = 'not_started';
        challenge.photoData = null;
        challenge.verificationResult = null;
        this.renderActiveLevel();
      });
    });

    // Verify photo button
    grid.querySelectorAll('.btn-verify').forEach(btn => {
      btn.addEventListener('click', () => {
        const idx = parseInt(btn.getAttribute('data-index'));
        this.triggerVerification(idx);
      });
    });

    // Done Buttons across Header, Banner, and Footer (User Request)
    const onDoneClick = () => {
      const levelData = this.currentQuest.levels[this.currentLevel];
      const allDone = levelData.challenges.every(c => c.status === 'completed');
      if (allDone) {
        this.handleLevelCompleted();
      }
    };

    this.container.querySelector('#btn-level-done-header')?.addEventListener('click', onDoneClick);
    this.container.querySelector('#btn-level-done-banner')?.addEventListener('click', onDoneClick);
    this.container.querySelector('#btn-level-done-footer')?.addEventListener('click', onDoneClick);
  }

  handlePhotoSelected(idx, dataUrl) {
    const challenge = this.currentQuest.levels[this.currentLevel].challenges[idx];
    challenge.photoData = dataUrl;
    challenge.status = 'selected';
    AudioService.playShutter();
    this.renderActiveLevel();
  }

  /**
   * Live Camera Viewfinder Modal with WebRTC (Requirement #11)
   */
  async openLiveCameraModal(idx) {
    const modalBackdrop = document.createElement('div');
    modalBackdrop.className = 'modal-backdrop active';
    modalBackdrop.innerHTML = `
      <div class="modal-dialog" style="max-width: 600px;">
        <button class="modal-close-btn" id="btn-close-camera">✕</button>
        <div class="camera-container">
          <h3 style="font-size: 1.25rem; font-weight: 800; color: var(--color-forest); margin-bottom: 0.5rem;">
            📸 Real World Viewfinder
          </h3>
          <p style="font-size: 0.88rem; color: var(--color-text-muted); margin-bottom: 1.25rem;">
            Align your discovery within the natural light.
          </p>

          <div class="camera-viewport">
            <video class="camera-video" id="live-camera-feed" autoplay playsinline></video>
            <div class="viewfinder-reticle">
              <div class="reticle-corner reticle-tl"></div>
              <div class="reticle-corner reticle-tr"></div>
              <div class="reticle-corner reticle-bl"></div>
              <div class="reticle-corner reticle-br"></div>
              <div class="reticle-center"></div>
            </div>
          </div>

          <div class="camera-controls">
            <button class="shutter-btn" id="btn-camera-shutter" title="Capture Discovery"></button>
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(modalBackdrop);

    const video = modalBackdrop.querySelector('#live-camera-feed');
    let stream = null;

    try {
      stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 960 } }
      });
      video.srcObject = stream;
      this.activeCameraStream = stream;
    } catch (err) {
      console.warn('Camera access not granted or unavailable:', err);
      // Fallback message inside viewport
      const viewport = modalBackdrop.querySelector('.camera-viewport');
      viewport.innerHTML = `
        <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; height:100%; color:#FFF; padding:2rem; text-align:center;">
          <div style="font-size:2.5rem; margin-bottom:1rem;">📷</div>
          <p style="font-size:0.95rem; margin-bottom:1rem;">Live webcam permission unavailable in this browser session.</p>
          <label class="btn btn-primary" style="cursor:pointer;">
            Select Photo File Instead
            <input type="file" accept="image/*" id="camera-modal-file-fallback" style="display:none;">
          </label>
        </div>
      `;

      viewport.querySelector('#camera-modal-file-fallback')?.addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (file) {
          const reader = new FileReader();
          reader.onload = (re) => {
            modalBackdrop.remove();
            this.handlePhotoSelected(idx, re.target.result);
          };
          reader.readAsDataURL(file);
        }
      });
    }

    const closeCamera = () => {
      if (this.activeCameraStream) {
        this.activeCameraStream.getTracks().forEach(t => t.stop());
        this.activeCameraStream = null;
      }
      modalBackdrop.remove();
    };

    modalBackdrop.querySelector('#btn-close-camera')?.addEventListener('click', closeCamera);

    modalBackdrop.querySelector('#btn-camera-shutter')?.addEventListener('click', () => {
      if (!video || !video.videoWidth) return;

      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(video, 0, 0);
      const dataUrl = canvas.toDataURL('image/jpeg', 0.85);

      closeCamera();
      this.handlePhotoSelected(idx, dataUrl);
    });
  }

  /**
   * AI Photo Verification Execution (Requirements #12, #16)
   */
  async triggerVerification(idx) {
    const challenge = this.currentQuest.levels[this.currentLevel].challenges[idx];
    challenge.status = 'verifying';
    this.renderActiveLevel();

    // Call open-weight vision model service
    const outcome = await PhotoVerificationService.verifyPhoto(challenge.photoData, challenge);
    challenge.verificationResult = outcome;

    if (outcome.status === 'PASS') {
      challenge.status = 'completed';
      AudioService.playSuccess();

      // Record to history and award XP
      ChallengeHistoryService.recordCompletedChallenge(challenge, {
        previewUrl: challenge.photoData,
        reason: outcome.reason
      });
      PlayerProgressService.awardChallengeXP(this.currentLevel);
      this.onRefreshNavbar();

      this.renderActiveLevel();

      // Check if current level is complete!
      const levelData = this.currentQuest.levels[this.currentLevel];
      const allDone = levelData.challenges.every(c => c.status === 'completed');
      if (allDone) {
        // Play celebratory chime and particles, keeping user on screen with active Done button
        AudioService.playSuccess();
        fireConfetti(2500);
      }
    } else {
      challenge.status = 'failed';
      challenge.attempts = (challenge.attempts || 0) + 1;
      this.retriesThisQuest++;
      PlayerProgressService.recordRetry();
      AudioService.playFailure();
      this.renderActiveLevel();
    }
  }

  /**
   * Level Completed Transitions (Requirements #14, #17, #20)
   */
  handleLevelCompleted() {
    this.stopTimer();

    if (this.currentLevel === 1) {
      this.showLevel1CompletedModal();
    } else if (this.currentLevel === 2) {
      this.showLevel2CompletedModal();
    } else if (this.currentLevel === 3) {
      this.showQuestCompletedCelebration();
    }
  }

  showLevel1CompletedModal() {
    AudioService.playSuccess();
    const minsLeft = Math.floor(this.timeRemaining / 60);
    const secsLeft = this.timeRemaining % 60;
    const timeSavedStr = (minsLeft > 0 || secsLeft > 0) ? `with ${minsLeft}m ${secsLeft}s to spare!` : '';

    const modalBackdrop = document.createElement('div');
    modalBackdrop.className = 'modal-backdrop active';
    modalBackdrop.innerHTML = `
      <div class="modal-dialog">
        <div class="celebration-modal">
          <div class="celebration-icon">🟢</div>
          <h2 class="celebration-title">LEVEL 1 COMPLETE ✓</h2>
          <p class="celebration-subtitle">
            “You stopped looking at the obvious. Now look closer.”
          </p>

          <div style="font-size: 1.1rem; font-weight: 700; color: var(--color-primary); margin-bottom: 0.75rem;">
            4 / 4 discoveries captured ${timeSavedStr}
          </div>

          <div style="margin-bottom: 2rem;">
            <span class="ready-badge" style="background: var(--color-primary-soft); color: var(--color-primary);">
              ⚡ Beat the Clock Speed Bonus Awarded
            </span>
          </div>

          <button class="btn btn-primary btn-lg" id="btn-continue-level-2">
            Done! Continue to Round 2 (Observer) →
          </button>
          <div style="font-size: 0.8rem; color: var(--color-text-muted); margin-top: 1rem;">
            Take a breather. The Level 2 timer will only start when you click Continue.
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(modalBackdrop);
    modalBackdrop.querySelector('#btn-continue-level-2')?.addEventListener('click', () => {
      modalBackdrop.remove();
      this.startLevel(2);
    });
  }

  showLevel2CompletedModal() {
    AudioService.playSuccess();
    const minsLeft = Math.floor(this.timeRemaining / 60);
    const secsLeft = this.timeRemaining % 60;
    const timeSavedStr = (minsLeft > 0 || secsLeft > 0) ? `with ${minsLeft}m ${secsLeft}s to spare!` : '';

    const modalBackdrop = document.createElement('div');
    modalBackdrop.className = 'modal-backdrop active';
    modalBackdrop.innerHTML = `
      <div class="modal-dialog">
        <div class="celebration-modal">
          <div class="celebration-icon">🟡</div>
          <h2 class="celebration-title">LEVEL 2 COMPLETE ✓</h2>
          <p class="celebration-subtitle">
            “Your eyes are getting sharper. One final level.”
          </p>

          <div style="font-size: 1.1rem; font-weight: 700; color: var(--color-sun-gold); margin-bottom: 0.75rem;">
            3 / 3 discoveries captured ${timeSavedStr}
          </div>

          <div style="margin-bottom: 2rem;">
            <span class="ready-badge" style="background: #FFF8E1; color: var(--color-sun-gold);">
              ⚡ Observer Speed Bonus Awarded
            </span>
          </div>

          <button class="btn btn-terracotta btn-lg" id="btn-continue-level-3">
            Done! Enter Round 3 (Creative Explorer) →
          </button>
          <div style="font-size: 0.8rem; color: var(--color-text-muted); margin-top: 1rem;">
            Level 3 contains 2 creative twists with a 15-minute countdown.
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(modalBackdrop);
    modalBackdrop.querySelector('#btn-continue-level-3')?.addEventListener('click', () => {
      modalBackdrop.remove();
      this.startLevel(3);
    });
  }

  /**
   * Final Quest Complete Celebration (Requirements #20, #21)
   */
  showQuestCompletedCelebration() {
    AudioService.playFanfare();
    fireConfetti(5000);

    const elapsedSeconds = this.questStartTime ? Math.round((Date.now() - this.questStartTime) / 1000) : 3600;
    const minsTaken = Math.floor(elapsedSeconds / 60);

    // Award full quest completion + check badges
    const progressResult = PlayerProgressService.awardFullQuestCompletion({
      durationSeconds: elapsedSeconds,
      retries: this.retriesThisQuest
    });

    this.onRefreshNavbar();

    // Collect all 9 captured photos from this quest
    const allPhotos = [
      ...this.currentQuest.levels[1].challenges,
      ...this.currentQuest.levels[2].challenges,
      ...this.currentQuest.levels[3].challenges
    ];

    this.container.innerHTML = `
      <div class="quest-wrapper">
        <div class="container container-narrow">
          <div class="quest-start-card" style="text-align: center;">
            <div class="celebration-icon" style="font-size: 4rem;">🏆</div>
            <h1 class="quest-start-title" style="font-size: 2.8rem; color: var(--color-forest);">
              QUEST COMPLETE!
            </h1>
            <p class="quest-start-subtitle" style="font-size: 1.25rem;">
              “You went looking. You found something.”
            </p>

            <div style="display: inline-block; background: var(--color-primary-soft); color: var(--color-primary); font-weight: 800; padding: 0.5rem 1.5rem; border-radius: var(--radius-full); margin-bottom: 2rem; font-size: 1.1rem;">
              9 / 9 discoveries captured
            </div>

            <!-- Quest Stats Grid (Requirement #20) -->
            <div class="quest-stats-row">
              <div class="quest-stat-entry">
                <span class="quest-stat-value">3 / 3</span>
                <span class="quest-stat-label">Levels Done</span>
              </div>
              <div class="quest-stat-entry">
                <span class="quest-stat-value">9</span>
                <span class="quest-stat-label">Photos Captured</span>
              </div>
              <div class="quest-stat-entry">
                <span class="quest-stat-value">+385</span>
                <span class="quest-stat-label">XP Earned</span>
              </div>
              <div class="quest-stat-entry">
                <span class="quest-stat-value">${minsTaken}m</span>
                <span class="quest-stat-label">Total Time</span>
              </div>
            </div>

            <!-- Badge Unlocked Showcase (Requirement #21) -->
            <div class="unlocked-badge-showcase">
              <div class="unlocked-badge-art">
                <img src="badge_first_explorer.jpg" alt="First Explorer Badge">
              </div>
              <div>
                <div style="font-size: 0.8rem; font-weight: 800; color: #B7791F; text-transform: uppercase;">
                  🎉 Badge Unlocked!
                </div>
                <h3 style="font-size: 1.3rem; font-weight: 850; color: var(--color-forest); margin: 0.2rem 0;">
                  🏅 First Explorer
                </h3>
                <p style="font-size: 0.88rem; color: var(--color-text-muted);">
                  Completed your first three-level TouchQuest outdoor expedition.
                </p>
              </div>
            </div>

            <!-- Action Buttons (Requirements #21, #36) -->
            <div style="display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; margin-bottom: 2.5rem;">
              <button class="btn btn-primary btn-lg" id="btn-quest-play-again">
                Play Again →
              </button>
              <button class="btn btn-secondary" id="btn-view-badges">
                View My Badges
              </button>
              <button class="btn btn-secondary" id="btn-view-profile">
                View Profile
              </button>
              <button class="btn btn-secondary" id="btn-share-achievement">
                Share Achievement 📤
              </button>
            </div>

            <!-- 9 Photos Gallery for this Quest -->
            <div style="text-align: left; margin-top: 3rem; border-top: var(--border-light); padding-top: 2rem;">
              <h3 style="font-size: 1.3rem; font-weight: 800; color: var(--color-forest); margin-bottom: 0.5rem;">
                Your Quest Album (9 Discoveries)
              </h3>
              <p style="font-size: 0.88rem; color: var(--color-text-muted); margin-bottom: 1.5rem;">
                The real world answers you brought back today.
              </p>

              <div class="photo-gallery-grid">
                ${allPhotos.map(c => `
                  <div class="gallery-photo-card">
                    <img src="${c.photoData}" alt="${c.title}">
                    <div class="gallery-photo-info">
                      <div class="gallery-photo-title">${c.title}</div>
                      <div class="gallery-photo-level">Level ${c.level} • ${c.category}</div>
                      <div style="font-size: 0.72rem; color: var(--color-primary); margin-top: 0.2rem;">
                        ✓ Verified
                      </div>
                    </div>
                  </div>
                `).join('')}
              </div>
            </div>
          </div>
        </div>
      </div>
    `;

    // Attach listeners
    this.container.querySelector('#btn-quest-play-again')?.addEventListener('click', () => {
      this.startAIQuestGeneration();
    });

    this.container.querySelector('#btn-view-badges')?.addEventListener('click', () => {
      this.onNavigate('badges');
    });

    this.container.querySelector('#btn-view-profile')?.addEventListener('click', () => {
      this.onNavigate('profile');
    });

    this.container.querySelector('#btn-share-achievement')?.addEventListener('click', () => {
      const shareText = `I completed TouchQuest! 🌿 9 real-world outdoor photo challenges verified by open-weight AI in 3 levels. Stop scrolling, start exploring! #TouchGrass #TouchQuest`;
      if (navigator.share) {
        navigator.share({ title: 'TouchQuest Complete', text: shareText, url: window.location.href }).catch(() => {});
      } else {
        navigator.clipboard.writeText(shareText);
        alert('Achievement copied to clipboard! Share it with friends.');
      }
    });
  }
}


  // ==========================================
  // MODULE: Navbar.js
  // ==========================================



function renderNavbar(container, onNavigate, onStartQuest) {
  const profile = PlayerProgressService.getProfile();
  const settings = StorageService.getSettings();

  container.innerHTML = `
    <header class="site-header">
      <div class="container nav-container">
        <a href="#home" class="brand-logo" id="nav-brand-logo">
          <div class="logo-icon">🌿</div>
          <span>TouchQuest</span>
        </a>

        <ul class="nav-links">
          <li><a href="#home" class="nav-link active" data-nav="home">Home</a></li>
          <li><a href="#how-it-works" class="nav-link" data-nav="how-it-works">How It Works</a></li>
          <li><a href="#levels" class="nav-link" data-nav="levels">3 Levels</a></li>
          <li><a href="#badges" class="nav-link" data-nav="badges">Badges</a></li>
          <li><a href="#profile" class="nav-link" data-nav="profile">Profile</a></li>
          <li><a href="#open-ai" class="nav-link" data-nav="open-ai">Open AI</a></li>
        </ul>

        <div class="nav-actions">
          <button class="player-stat-pill" id="navbar-profile-pill" title="View Profile">
            <span>⚡ ${profile.xp} XP</span>
            <span>🔥 ${profile.currentStreak || 1}d</span>
          </button>

          <button class="sound-toggle-btn" id="navbar-sound-toggle" title="Toggle Sound Feedback">
            ${settings.soundEnabled !== false ? '🔊' : '🔇'}
          </button>

          <button class="btn btn-primary" id="navbar-start-btn">
            Start Quest →
          </button>

          <button class="mobile-menu-btn" id="navbar-mobile-toggle" aria-label="Toggle menu">
            ☰
          </button>
        </div>
      </div>
    </header>
  `;

  // Attach event listeners
  const brandLogo = container.querySelector('#nav-brand-logo');
  brandLogo?.addEventListener('click', (e) => {
    e.preventDefault();
    onNavigate('home');
  });

  const links = container.querySelectorAll('.nav-link');
  links.forEach(link => {
    link.addEventListener('click', (e) => {
      e.preventDefault();
      const target = link.getAttribute('data-nav');
      links.forEach(l => l.classList.remove('active'));
      link.classList.add('active');
      onNavigate(target);
    });
  });

  const profilePill = container.querySelector('#navbar-profile-pill');
  profilePill?.addEventListener('click', () => {
    onNavigate('profile');
  });

  const startBtn = container.querySelector('#navbar-start-btn');
  startBtn?.addEventListener('click', () => {
    onStartQuest();
  });

  const soundBtn = container.querySelector('#navbar-sound-toggle');
  soundBtn?.addEventListener('click', () => {
    const currSettings = StorageService.getSettings();
    currSettings.soundEnabled = !currSettings.soundEnabled;
    StorageService.saveSettings(currSettings);
    soundBtn.innerHTML = currSettings.soundEnabled ? '🔊' : '🔇';
    if (currSettings.soundEnabled) {
      AudioService.playShutter();
    }
  });

  const mobileBtn = container.querySelector('#navbar-mobile-toggle');
  mobileBtn?.addEventListener('click', () => {
    const navLinks = container.querySelector('.nav-links');
    if (navLinks) {
      const isVisible = navLinks.style.display === 'flex';
      navLinks.style.display = isVisible ? 'none' : 'flex';
      navLinks.style.flexDirection = 'column';
      navLinks.style.position = 'absolute';
      navLinks.style.top = '72px';
      navLinks.style.left = '0';
      navLinks.style.right = '0';
      navLinks.style.background = '#FFFFFF';
      navLinks.style.padding = '1.5rem';
      navLinks.style.borderBottom = 'var(--border-light)';
      navLinks.style.boxShadow = 'var(--shadow-md)';
    }
  });
}


